/* DAWAH X — ahmad, অধ্যায় 37 · খণ্ড 37 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][37]=[[7201,7201,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَصْلَحَ خَادِمُ أَحَدِكُمْ لَهُ طَعَامَهُ فَكَفَاهُ حَرَّهُ وَبَرْدَهُ فَلْيُجْلِسْهُ مَعَهُ فَإِنْ أَبَى فَلْيُنَاوِلْهُ أُكْلَةً فِي يَدِهِ ‏","","",""],[7202,7202,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏أُقِيمَتْ الصَّلَاةُ فَجَاءَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَامَ فِي مُصَلَّاهُ فَذَكَرَ أَنَّهُ لَمْ يَغْتَسِلْ فَانْصَرَفَ ثُمَّ قَالَ كَمَا أَنْتُمْ فَصَفَفْنَا وَإِنَّ رَأْسَهُ لَيَنْطِفُ فَصَلَّى بِنَا ‏","","",""],[7203,7203,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا رَأَيْتُمْ الْهِلَالَ فَصُومُوا وَإِذَا رَأَيْتُمُوهُ فَأَفْطِرُوا فَإِنْ ‏ ‏غُمَّ ‏ ‏عَلَيْكُمْ فَصُومُوا ثَلَاثِينَ يَوْمًا ‏","","",""],[7204,7204,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا قَامَ أَحَدُكُمْ مِنْ اللَّيْلِ فَلَا ‏ ‏يَغْمِسْ ‏ ‏يَدَهُ فِي إِنَائِهِ حَتَّى يَغْسِلَهَا ثَلَاثًا فَإِنَّهُ لَا يَدْرِي أَيْنَ بَاتَتْ يَدُهُ ‏","","",""],[7205,7205,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَقُولُوا ‏ ‏خَيْبَةَ ‏ ‏الدَّهْرِ إِنَّ اللَّهَ هُوَ الدَّهْرُ وَلَا تُسَمُّوا الْعِنَبَ الْكَرْمَ ‏","","",""],[7206,7206,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏الْأَغَرِّ أَبِي عَبْدِ اللَّهِ ‏ ‏صَاحِبِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا كَانَ يَوْمُ الْجُمُعَةِ قَعَدَتْ الْمَلَائِكَةُ عَلَى أَبْوَابِ الْمَسْجِدِ فَكَتَبُوا مَنْ جَاءَ إِلَى الْجُمُعَةِ فَإِذَا خَرَجَ الْإِمَامُ طَوَتْ الْمَلَائِكَةُ الصُّحُفَ وَدَخَلَتْ تَسْمَعُ الذِّكْرَ ‏","","",""],[7207,7207,"","","‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمُهَجِّرُ ‏ ‏إِلَى الْجُمُعَةِ كَالْمُهْدِي ‏ ‏بَدَنَةً ‏ ‏ثُمَّ كَالْمُهْدِي بَقَرَةً ثُمَّ كَالْمُهْدِي شَاةً ثُمَّ كَالْمُهْدِي بَطَّةً ثُمَّ كَالْمُهْدِي دَجَاجَةً ثُمَّ كَالْمُهْدِي بَيْضَةً ‏","","",""],[7208,7208,"","","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ خَالِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ اللَّيْثِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُئِلَ عَنْ أَوْلَادِ الْمُشْرِكِينَ فَقَالَ ‏ ‏اللَّهُ أَعْلَمُ بِمَا كَانُوا عَامِلِينَ ‏","","",""],[7209,7209,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ الْحَدَّادُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ اللَّهُ عَزَّ وَجَلَّ ‏ ‏وَمَنْ أَظْلَمُ مِمَّنْ يَخْلُقُ كَخَلْقِي فَلْيَخْلُقُوا بَعُوضَةً أَوْ لِيَخْلُقُوا ذَرَّةً ‏","","",""],[7210,7210,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ فَرَاهِيجَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا زَالَ ‏ ‏جِبْرِيلُ ‏ ‏يُوصِينِي بِالْجَارِ حَتَّى ظَنَنْتُ أَنَّهُ سَيُوَرِّثُهُ ‏","","",""],[7211,7211,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ ‏ ‏عَنْ ‏ ‏عَوْفٍ ‏ ‏عَنْ ‏ ‏خِلَاسِ بْنِ عَمْرٍو ‏ ‏وَمُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ اشْتَرَى ‏ ‏لِقْحَةً ‏ ‏مُصَرَّاةً ‏ ‏أَوْ شَاةً ‏ ‏مُصَرَّاةً ‏ ‏فَحَلَبَهَا فَهُوَ بِأَحَدِ ‏ ‏النَّظَرَيْنِ ‏ ‏بِالْخِيَارِ ‏ ‏إِلَى أَنْ يَحُوزَهَا أَوْ يَرُدَّهَا وَإِنَاءً مِنْ طَعَامٍ ‏","","",""],[7212,7212,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ ‏ ‏عَنْ ‏ ‏عَوْفٍ ‏ ‏عَنْ ‏ ‏خِلَاسٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَثَلُ الَّذِي ‏ ‏يَعُودُ ‏ ‏فِي عَطِيَّتِهِ كَمَثَلِ الْكَلْبِ يَأْكُلُ حَتَّى إِذَا شَبِعَ قَاءَ ثُمَّ عَادَ فِي قَيْئِهِ فَأَكَلَهُ ‏","","",""],[7213,7213,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ ‏ ‏عَنْ ‏ ‏عَوْفٍ ‏ ‏عَنْ ‏ ‏خِلَاسٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَبُولَنَّ أَحَدُكُمْ فِي الْمَاءِ ‏ ‏الدَّائِمِ ‏ ‏ثُمَّ يَتَوَضَّأُ مِنْهُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ ‏ ‏حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏مِثْلَهُ ‏","","",""],[7214,7214,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تُسْتَأْمَرُ ‏ ‏الْيَتِيمَةُ فِي نَفْسِهَا فَإِنْ سَكَتَتْ فَهُوَ إِذْنُهَا وَإِنْ أَبَتْ فَلَا ‏ ‏جَوَازَ ‏ ‏عَلَيْهَا ‏","","",""],[7215,7215,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ حَفْصٍ ‏ ‏أَخْبَرَنَا ‏ ‏وَرْقَاءُ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمَّا خَلَقَ اللَّهُ الْخَلْقَ كَتَبَ كِتَابًا فَهُوَ عِنْدَهُ فَوْقَ الْعَرْشِ ‏ ‏إِنَّ رَحْمَتِي سَبَقَتْ غَضَبِي ‏","","",""],[7216,7216,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ حَفْصٍ ‏ ‏أَخْبَرَنَا ‏ ‏وَرْقَاءُ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حُفَّتْ ‏ ‏النَّارُ بِالشَّهَوَاتِ ‏ ‏وَحُفَّتْ ‏ ‏الْجَنَّةُ بِالْمَكَارِهِ ‏","","",""],[7217,7217,"","","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو مَوْدُودٍ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي حَدْرَدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ‏ ‏بَزَقَ ‏ ‏أَحَدُكُمْ فِي الْمَسْجِدِ فَلْيَدْفِنْهُ فَإِنْ لَمْ يَفْعَلْ ‏ ‏فَلْيَبْزُقْ ‏ ‏فِي ثَوْبِهِ ‏","","",""],[7218,7218,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ الثَّقَفِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَسَمَّوْا بِاسْمِي وَلَا تَكَنَّوْا بِكُنْيَتِي ‏","","",""],[7219,7219,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏يُونُسَ يَعْنِي ابْنَ عُبَيْدٍ ‏ ‏عَنْ ‏ ‏الصَّلْتِ بْنِ غَالِبٍ الْهُجَيْمِيِّ ‏ ‏عَنْ ‏ ‏مُسْلِمٍ ‏ ‏سَأَلَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏عَنْ الشُّرْبِ قَائِمًا قَالَ يَا ابْنَ أَخِي رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَقَلَ ‏ ‏رَاحِلَتَهُ ‏ ‏وَهِيَ ‏ ‏مُنَاخَةٌ ‏ ‏وَأَنَا آخِذٌ ‏ ‏بِخِطَامِهَا ‏ ‏أَوْ ‏ ‏زِمَامِهَا ‏ ‏وَاضِعًا رِجْلِي عَلَى يَدِهَا فَجَاءَ ‏ ‏نَفَرٌ ‏ ‏مِنْ ‏ ‏قُرَيْشٍ ‏ ‏فَقَامُوا حَوْلَهُ فَأُتِيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِإِنَاءٍ مِنْ لَبَنٍ ‏ ‏فَشَرِبَ وَهُوَ عَلَى ‏ ‏رَاحِلَتِهِ ‏ ‏ثُمَّ نَاوَلَ الَّذِي يَلِيهِ عَنْ يَمِينِهِ فَشَرِبَ قَائِمًا حَتَّى شَرِبَ الْقَوْمُ كُلُّهُمْ قِيَامًا ‏","","",""],[7220,7220,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَوْ قَالَ ‏ ‏أَبُو الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَا يَخَافُ الَّذِي يَرْفَعُ رَأْسَهُ وَالْإِمَامُ سَاجِدٌ أَنْ يُحَوِّلَ اللَّهُ رَأْسَهُ رَأْسَ حِمَارٍ ‏","","",""],[7221,7221,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏يُونُسَ يَعْنِي ابْنَ عُبَيْدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا يُؤْمِنُ الَّذِي رَفَعَ رَأْسَهُ قَبْلَ الْإِمَامِ وَهُوَ مَعَ الْإِمَامِ أَنْ يُحَوِّلَ اللَّهُ صُورَتَهُ صُورَةَ حِمَارٍ ‏","","",""],[7222,7222,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏أَوْصَانِي خَلِيلِي بِثَلَاثٍ ‏ ‏صَوْمُ ثَلَاثَةِ أَيَّامٍ مِنْ كُلِّ شَهْرٍ ‏ ‏وَالْوِتْرُ ‏ ‏قَبْلَ النَّوْمِ وَالْغُسْلُ يَوْمَ الْجُمُعَةِ ‏","","",""],[7223,7223,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏ذَكَرُوا عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلًا ‏ ‏أَوْ أَنَّ رَجُلًا قَالَ يَا رَسُولَ اللَّهِ ‏ ‏إِنَّ فُلَانًا نَامَ الْبَارِحَةَ وَلَمْ يُصَلِّ حَتَّى أَصْبَحَ قَالَ ‏ ‏بَالَ الشَّيْطَانُ فِي أُذُنِهِ ‏","","",""],[7224,7224,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَدْرَكَ رَكْعَةً مِنْ صَلَاةِ الْفَجْرِ قَبْلَ أَنْ تَطْلُعَ الشَّمْسُ فَقَدْ أَدْرَكَهَا وَمَنْ أَدْرَكَ رَكْعَةً مِنْ صَلَاةِ الْعَصْرِ قَبْلَ أَنْ تَغْرُبَ الشَّمْسُ فَقَدْ أَدْرَكَهَا ‏","","",""],[7225,7225,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيْسَ الْمِسْكِينُ الَّذِي تَرُدُّهُ التَّمْرَةُ وَالتَّمْرَتَانِ وَالْأُكْلَةُ وَالْأُكْلَتَانِ قَالُوا فَمَنْ الْمِسْكِينُ يَا رَسُولَ اللَّهِ قَالَ الَّذِي لَا يَجِدُ غِنًى وَلَا يَعْلَمُ النَّاسُ بِحَاجَتِهِ فَيُتَصَدَّقَ عَلَيْهِ ‏ ‏قَالَ ‏ ‏الزُّهْرِيُّ ‏ ‏وَذَلِكَ هُوَ الْمَحْرُومُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِثْلِ هَذَا الْحَدِيثِ غَيْرَ أَنَّهُ قَالَ قَالُوا يَا رَسُولَ اللَّهِ فَمَنْ الْمِسْكِينُ قَالَ الَّذِي لَيْسَ لَهُ غِنًى وَلَا يَسْأَلُ النَّاسَ ‏ ‏إِلْحَافًا ‏","","",""],[7226,7226,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏هَمَّامِ بْنِ مُنَبِّهٍ ‏ ‏أَخِي ‏ ‏وَهْبٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَطْلُ ‏ ‏الْغَنِيِّ ظُلْمٌ ‏","","",""],[7227,7227,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْيَهُودُ ‏ ‏وَالنَّصَارَى ‏ ‏لَا يَصْبُغُونَ فَخَالِفُوا عَلَيْهِمْ ‏","","",""],[7228,7228,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏النَّاسُ ‏ ‏مَعَادِنُ ‏ ‏خِيَارُهُمْ فِي الْجَاهِلِيَّةِ خِيَارُهُمْ فِي الْإِسْلَامِ إِذَا ‏ ‏فَقِهُوا ‏","","",""],[7229,7229,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏وَيَزِيدُ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فُجِّرَتْ أَرْبَعَةُ أَنْهَارٍ مِنْ الْجَنَّةِ الْفُرَاتُ وَالنِّيلُ ‏ ‏وَسَيْحَانُ ‏ ‏وَجَيْحَانُ ‏","","",""],[7230,7230,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏وَابْنُ نُمَيْرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَيِّرُوا الشَّيْبَ وَلَا تَشَبَّهُوا ‏ ‏بِالْيَهُودِ ‏ ‏وَلَا ‏ ‏بِالنَّصَارَى ‏","","",""],[7231,7231,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏وَابْنُ نُمَيْرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُؤْتَى بِالْمَوْتِ يَوْمَ الْقِيَامَةِ فَيُوقَفُ عَلَى ‏ ‏الصِّرَاطِ ‏ ‏فَيُقَالُ يَا أَهْلَ الْجَنَّةِ فَيَطَّلِعُونَ خَائِفِينَ ‏ ‏وَجِلِينَ ‏ ‏أَنْ يُخْرَجُوا ‏ ‏وَقَالَ ‏ ‏يَزِيدُ ‏ ‏أَنْ يُخْرَجُوا مِنْ مَكَانِهِمْ الَّذِي هُمْ فِيهِ ‏ ‏فَيُقَالُ هَلْ تَعْرِفُونَ هَذَا قَالُوا نَعَمْ رَبَّنَا هَذَا الْمَوْتُ ثُمَّ يُقَالُ يَا أَهْلَ النَّارِ فَيَطَّلِعُونَ فَرِحِينَ مُسْتَبْشِرِينَ أَنْ يُخْرَجُوا مِنْ مَكَانِهِمْ الَّذِي هُمْ فِيهِ فَيُقَالُ هَلْ تَعْرِفُونَ هَذَا قَالُوا نَعَمْ هَذَا الْمَوْتُ فَيَأْمُرُ بِهِ فَيُذْبَحُ عَلَى ‏ ‏الصِّرَاطِ ‏ ‏ثُمَّ يُقَالُ لِلْفَرِيقَيْنِ كِلَاهُمَا خُلُودٌ فِيمَا تَجِدُونَ لَا مَوْتَ فِيهِ أَبَدًا ‏","","",""],[7232,7232,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدٌ ‏ ‏وَابْنُ نُمَيْرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَتْ امْرَأَةٌ النَّارَ فِي ‏ ‏هِرَّةٍ ‏ ‏رَبَطَتْهَا فَلَمْ تُطْعِمْهَا وَلَمْ تَسْقِهَا وَلَمْ تُرْسِلْهَا فَتَأْكُلَ مِنْ ‏ ‏خَشَاشِ ‏ ‏الْأَرْضِ ‏","","",""],[7233,7233,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏وَيَزِيدُ ‏ ‏قَالَا أَنَا ‏ ‏مُحَمَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْوِصَالِ ‏ ‏قَالُوا إِنَّكَ ‏ ‏تُوَاصِلُ ‏ ‏قَالَ إِنَّكُمْ لَسْتُمْ كَهَيْئَتِي إِنَّ اللَّهَ حِبِّي يُطْعِمُنِي ‏ ‏وَيَسْقِينِ ‏ ‏وَقَالَ ‏ ‏يَزِيدُ ‏ ‏إِنِّي أَبِيتُ يُطْعِمُنِي رَبِّي ‏ ‏وَيَسْقِينِي ‏","","",""],[7234,7234,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏عَنْ ‏ ‏حَنْظَلَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَالِمًا ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُقْبَضُ الْعِلْمُ وَيَظْهَرُ ‏ ‏الْفِتَنُ ‏ ‏وَيَكْثُرُ ‏ ‏الْهَرْجُ ‏ ‏قِيلَ يَا رَسُولَ اللَّهِ وَمَا ‏ ‏الْهَرْجُ ‏ ‏قَالَ الْقَتْلُ ‏","","",""],[7235,7235,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏التَّسْبِيحُ لِلرِّجَالِ وَالتَّصْفِيقُ لِلنِّسَاءِ ‏","","",""],[7236,7236,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا صَلَّى أَحَدُكُمْ ثُمَّ جَلَسَ فِي مُصَلَّاهُ لَمْ تَزَلْ الْمَلَائِكَةُ تَقُولُ اللَّهُمَّ اغْفِرْ لَهُ اللَّهُمَّ ارْحَمْهُ مَا لَمْ ‏ ‏يُحْدِثْ ‏ ‏أَوْ ‏ ‏يَقُومْ ‏","","",""],[7237,7237,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى ‏ ‏وَيَزِيدُ ‏ ‏قَالَا أَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏مَرَّتْ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏مَرُّوا عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِجِنَازَةٍ فَأَثْنَوْا عَلَيْهَا خَيْرًا فِي مَنَاقِبِ الْخَيْرِ فَقَالَ وَجَبَتْ ثُمَّ مَرَّتْ عَلَيْهِ جَنَازَةٌ أُخْرَى فَأَثْنَوْا عَلَيْهَا شَرًّا فِي مَنَاقِبِ الشَّرِّ فَقَالَ وَجَبَتْ ثُمَّ قَالَ ‏ ‏إِنَّكُمْ شُهَدَاءُ فِي الْأَرْضِ ‏","","",""],[7238,7238,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى ‏ ‏وَيَزِيدُ ‏ ‏قَالَا أَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ رَآنِي فِي الْمَنَامِ فَقَدْ رَأَى الْحَقَّ إِنَّ الشَّيْطَانَ لَا يَتَشَبَّهُ بِي ‏","","",""],[7239,7239,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَحْسِرُ ‏ ‏الْفُرَاتُ عَنْ جَبَلٍ مِنْ ذَهَبٍ فَيَقْتَتِلُ النَّاسُ عَلَيْهِ فَيُقْتَلُ مِنْ كُلِّ عَشَرَةٍ تِسْعَةٌ ‏","","",""],[7240,7240,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ الْغِنَى عَنْ كَثْرَةِ ‏ ‏الْعَرَضِ ‏ ‏وَلَكِنَّ الْغِنَى غِنَى النَّفْسِ ‏","","",""],[7241,7241,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى ‏ ‏وَيَزِيدُ ‏ ‏قَالَا أَنَا ‏ ‏مُحَمَّدٌ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏النَّاسُ تَبَعٌ ‏ ‏لِقُرَيْشٍ ‏ ‏فِي هَذَا الْأَمْرِ خِيَارُهُمْ تَبَعٌ لِخِيَارِهِمْ وَشِرَارُهُمْ تَبَعٌ لِشِرَارِهِمْ ‏","","",""],[7242,7242,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏وَيَعْلَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فِي الْحَبَّةِ السَّوْدَاءِ شِفَاءٌ مِنْ كُلِّ دَاءٍ إِلَّا ‏ ‏السَّامَ ‏ ‏قَالُوا يَا رَسُولَ اللَّهِ وَمَا ‏ ‏السَّامُ ‏ ‏قَالَ الْمَوْتُ ‏","","",""],[7243,7243,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏فُضَيْلٌ يَعْنِي ابْنَ غَزْوَانَ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي نُعْمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْفِضَّةُ بِالْفِضَّةِ مِثْلًا بِمِثْلٍ وَزْنًا بِوَزْنٍ وَالذَّهَبُ بِالذَّهَبِ وَزْنًا بِوَزْنٍ مِثْلًا بِمِثْلٍ فَمَنْ زَادَ فَهُوَ رِبًا وَلَا تُبَاعُ ثَمَرَةٌ حَتَّى يَبْدُوَ صَلَاحُهَا ‏","","",""],[7244,7244,"","","‏ ‏حَدَّثَنَا ‏ ‏رِبْعِيُّ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ يَعْنِي ابْنَ إِسْحَقَ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ثَلَاثٌ مِنْ عَمَلِ أَهْلِ الْجَاهِلِيَّةِ لَا يَتْرُكُهُنَّ أَهْلُ الْإِسْلَامِ ‏ ‏النِّيَاحَةُ ‏ ‏وَالِاسْتِسْقَاءُ ‏ ‏بِالْأَنْوَاءِ ‏ ‏وَكَذَا قُلْتُ ‏ ‏لِسَعِيدٍ ‏ ‏وَمَا هُوَ قَالَ ‏ ‏دَعْوَى الْجَاهِلِيَّةِ يَا آلَ فُلَانٍ يَا آلَ فُلَانٍ يَا آلَ فُلَانٍ ‏","","",""],[7245,7245,"","","‏ ‏حَدَّثَنَا ‏ ‏رِبْعِيٌّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ صَلَّى عَلَيَّ مَرَّةً وَاحِدَةً كَتَبَ اللَّهُ عَزَّ وَجَلَّ لَهُ بِهَا عَشْرَ حَسَنَاتٍ ‏","","",""],[7246,7246,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ صَلَّى عَلَيَّ مَرَّةً وَاحِدَةً كَتَبَ اللَّهُ عَزَّ وَجَلَّ لَهُ بِهَا عَشْرَ حَسَنَاتٍ ‏","","",""],[7247,7247,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏سُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ صَاحِبِ كَنْزٍ لَا يُؤَدِّي حَقَّهُ إِلَّا جُعِلَ صَفَائِحَ ‏ ‏يُحْمَى عَلَيْهَا فِي نَارِ جَهَنَّمَ فَتُكْوَى بِهَا جَبْهَتُهُ وَجَنْبُهُ وَظَهْرُهُ حَتَّى يَحْكُمَ اللَّهُ عَزَّ وَجَلَّ بَيْنَ عِبَادِهِ فِي يَوْمٍ كَانَ مِقْدَارُهُ خَمْسِينَ أَلْفَ سَنَةٍ مِمَّا تَعُدُّونَ ثُمَّ يُرَى سَبِيلَهُ إِمَّا إِلَى الْجَنَّةِ وَإِمَّا إِلَى النَّارِ وَمَا مِنْ صَاحِبِ غَنَمٍ لَا يُؤَدِّي حَقَّهَا إِلَّا جَاءَتْ يَوْمَ الْقِيَامَةِ ‏ ‏أَوْفَرَ ‏ ‏مَا كَانَتْ ‏ ‏فَيُبْطَحُ ‏ ‏لَهَا ‏ ‏بِقَاعٍ ‏ ‏قَرْقَرٍ ‏ ‏فَتَنْطَحُهُ بِقُرُونِهَا ‏ ‏وَتَطَؤُهُ ‏ ‏بِأَظْلَافِهَا ‏ ‏لَيْسَ فِيهَا ‏ ‏عَقْصَاءُ ‏ ‏وَلَا ‏ ‏جَلْحَاءُ ‏ ‏كُلَّمَا مَضَتْ أُخْرَاهَا رُدَّتْ عَلَيْهِ أُولَاهَا حَتَّى يَحْكُمَ اللَّهُ عَزَّ وَجَلَّ بَيْنَ عِبَادِهِ فِي يَوْمٍ كَانَ مِقْدَارُهُ خَمْسِينَ أَلْفَ سَنَةٍ مِمَّا تَعُدُّونَ ثُمَّ يَرَى سَبِيلَهُ إِمَّا إِلَى الْجَنَّةِ وَإِمَّا إِلَى النَّارِ وَمَا مِنْ صَاحِبِ إِبِلٍ لَا يُؤَدِّي حَقَّهَا إِلَّا جَاءَتْ يَوْمَ الْقِيَامَةِ ‏ ‏أَوْفَرَ ‏ ‏مَا كَانَتْ ‏ ‏فَيُبْطَحُ ‏ ‏لَهَا ‏ ‏بِقَاعٍ ‏ ‏قَرْقَرٍ ‏ ‏فَتَطَؤُهُ ‏ ‏بِأَخْفَافِهَا ‏ ‏كُلَّمَا مَضَتْ أُخْرَاهَا رُدَّتْ عَلَيْهِ أُولَاهَا حَتَّى يَحْكُمَ اللَّهُ بَيْنَ عِبَادِهِ فِي يَوْمٍ كَانَ مِقْدَارُهُ خَمْسِينَ أَلْفَ سَنَةٍ مِمَّا تَعُدُّونَ ثُمَّ يَرَى سَبِيلَهُ إِمَّا إِلَى الْجَنَّةِ وَإِمَّا إِلَى النَّارِ ثُمَّ سُئِلَ عَنْ الْخَيْلِ فَقَالَ الْخَيْلُ ‏ ‏مَعْقُودٌ ‏ ‏فِي ‏ ‏نَوَاصِيهَا ‏ ‏الْخَيْرُ إِلَى يَوْمِ الْقِيَامَةِ وَهِيَ لِرَجُلٍ أَجْرٌ وَلِرَجُلٍ سِتْرٌ وَجَمَالٌ وَعَلَى رَجُلٍ ‏ ‏وِزْرٌ ‏ ‏أَمَّا الَّذِي هِيَ لَهُ أَجْرٌ فَرَجُلٌ يَتَّخِذُهَا يُعِدُّهَا فِي سَبِيلِ اللَّهِ فَمَا غَيَّبَتْ فِي بُطُونِهَا فَهُوَ لَهُ أَجْرٌ وَإِنْ مَرَّتْ بِنَهَرٍ فَشَرِبَتْ مِنْهُ فَمَا غَيَّبَتْ فِي بُطُونِهَا فَهُوَ لَهُ أَجْرٌ وَإِنْ مَرَّتْ فَمَا أَكَلَتْ مِنْهُ فَهُوَ لَهُ أَجْرٌ وَإِنْ ‏ ‏اسْتَنَّتْ ‏ ‏شَرَفًا فَلَهُ بِكُلِّ خُطْوَةٍ ‏ ‏تَخْطُوهَا أَجْرٌ حَتَّى ذَكَرَ ‏ ‏أَرْوَاثَهَا ‏ ‏وَأَبْوَالَهَا وَأَمَّا الَّتِي هِيَ لَهُ سِتْرٌ وَجَمَالٌ فَرَجُلٌ يَتَّخِذُهَا تَكَرُّمًا وَتَجَمُّلًا وَلَا ‏ ‏يَنْسَى حَقَّ بُطُونِهَا وَظُهُورِهَا وَعُسْرِهَا وَيُسْرِهَا وَأَمَّا الَّذِي هِيَ عَلَيْهِ ‏ ‏وِزْرٌ ‏ ‏فَرَجُلٌ يَتَّخِذُهَا بَذَخًا وَأَشَرًا ‏ ‏وَرِيَاءً ‏ ‏وَبَطَرًا ثُمَّ سُئِلَ عَنْ الْحُمُرِ فَقَالَ مَا أَنْزَلَ اللَّهُ عَلَيَّ فِيهَا إِلَّا الْآيَةَ ‏ ‏الْفَاذَّةَ ‏ ‏الْجَامِعَةَ ‏ { ‏مَنْ يَعْمَلْ ‏ ‏مِثْقَالَ ‏ ‏ذَرَّةٍ خَيْرًا يَرَهُ وَمَنْ يَعْمَلْ ‏ ‏مِثْقَالَ ‏ ‏ذَرَّةٍ شَرًّا يَرَهُ ‏}","","",""],[7248,7248,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏سُهَيْلٍ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏فِي حَدِيثِهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُهَيْلُ بْنُ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى يُمْطَرَ النَّاسُ مَطَرًا لَا تُكِنُّ مِنْهُ بُيُوتُ ‏ ‏الْمَدَرِ ‏ ‏وَلَا تُكِنُّ مِنْهُ إِلَّا بُيُوتُ الشَّعَرِ ‏","","",""],[7249,7249,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏سُهَيْلٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنَعَتْ ‏ ‏الْعِرَاقُ ‏ ‏قَفِيزَهَا ‏ ‏وَدِرْهَمَهَا وَمَنَعْتِ ‏ ‏الشَّامُ ‏ ‏مُدَّهَا ‏ ‏وَدِينَارَهَا وَمَنَعَتْ ‏ ‏مِصْرُ ‏ ‏إِرْدَبَّهَا وَدِينَارَهَا وَعُدْتُمْ مِنْ حَيْثُ بَدَأْتُمْ وَعُدْتُمْ مِنْ حَيْثُ بَدَأْتُمْ وَعُدْتُمْ مِنْ حَيْثُ بَدَأْتُمْ ‏ ‏يَشْهَدُ عَلَى ذَلِكَ لَحْمُ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَدَمُهُ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏سَمِعْتُ ‏ ‏يَحْيَى بْنَ مَعِينٍ ‏ ‏وَذَكَرَ ‏ ‏أَبَا كَامِلٍ ‏ ‏فَقَالَ كُنْتُ آخُذُ مِنْهُ ذَا الشَّأْنَ وَكَانَ ‏ ‏أَبُو كَامِلٍ ‏ ‏بَغْدَادِيًّا مِنْ الْأَبْنَاءِ ‏","","",""],[7250,7250,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏سُهَيْلٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَصْحَبُ الْمَلَائِكَةُ رُفْقَةً فِيهَا كَلْبٌ أَوْ جَرَسٌ ‏","","",""],[7251,7251,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏سُهَيْلُ بْنُ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا لَقِيتُمُوهُمْ فِي طَرِيقٍ فَلَا تَبْدَؤُهُمْ وَاضْطَرُّوهُمْ إِلَى أَضْيَقِهَا ‏ ‏قَالَ ‏ ‏زُهَيْرٌ ‏ ‏فَقُلْتُ ‏ ‏لِسُهَيْلٍ ‏ ‏الْيَهُودُ ‏ ‏وَالنَّصَارَى ‏ ‏فَقَالَ ‏ ‏الْمُشْرِكُونَ ‏","","",""],[7252,7252,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏سُهَيْلٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قَامَ الرَّجُلُ مِنْ مَجْلِسِهِ ثُمَّ رَجَعَ إِلَيْهِ فَهُوَ أَحَقُّ بِهِ ‏","","",""],[7253,7253,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏سُهَيْلٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ نَامَ وَفِي يَدِهِ ‏ ‏غَمَرٌ ‏ ‏وَلَمْ يَغْسِلْهُ فَأَصَابَهُ شَيْءٌ فَلَا يَلُومَنَّ إِلَّا نَفْسَهُ ‏","","",""],[7254,7254,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏سُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏يَجْزِي وَلَدٌ وَالِدَهُ إِلَّا أَنْ يَجِدَهُ مَمْلُوكًا فَيَشْتَرِيَهُ فَيُعْتِقَهُ ‏","","",""],[7255,7255,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ الْحَكَمِ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ أَبِي رَبَاحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ سُئِلَ عَنْ عِلْمٍ فَكَتَمَهُ ‏ ‏أُلْجِمَ ‏ ‏بِلِجَامٍ ‏ ‏مِنْ نَارٍ يَوْمَ الْقِيَامَةِ ‏","","",""],[7256,7256,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثُمَامَةَ بْنِ عَبْدِ اللَّهِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا وَقَعَ الذُّبَابُ فِي إِنَاءِ أَحَدِكُمْ فَلْيَغْمِسْهُ فَإِنَّ أَحَدَ جَنَاحَيْهِ دَاءٌ وَالْآخَرَ دَوَاءٌ ‏","","",""],[7257,7257,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏أَبِي الْمُهَزِّمِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ ‏ ‏فَاطِمَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏أَوْ ‏ ‏أُمَّ سَلَمَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏أَنْ تَجُرَّ ‏ ‏الذَّيْلَ ‏ ‏ذِرَاعًا ‏","","",""],[7258,7258,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏عَمَّارِ بْنِ أَبِي عَمَّارٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا أَطَاعَ الْعَبْدُ رَبَّهُ وَأَطَاعَ سَيِّدَهُ فَلَهُ أَجْرَانِ ‏","","",""],[7259,7259,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَجْتَمِعُ فِي النَّارِ مَنْ قَتَلَ كَافِرًا ثُمَّ ‏ ‏سَدَّدَ ‏ ‏بَعْدَهُ ‏","","",""],[7260,7260,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏أَبِي عِمْرَانَ الْجَوْنِيِّ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَجُلًا شَكَا إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَسْوَةَ قَلْبِهِ فَقَالَ لَهُ ‏ ‏إِنْ أَرَدْتَ تَلْيِينَ قَلْبِكَ فَأَطْعِمْ الْمِسْكِينَ وَامْسَحْ رَأْسَ الْيَتِيمِ ‏","","",""],[7261,7261,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ الْبُنَانِيِّ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ النَّهْدِيِّ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏صَوْمُ ‏ ‏شَهْرِ الصَّبْرِ ‏ ‏وَصَوْمُ ثَلَاثَةِ أَيَّامٍ مِنْ كُلِّ شَهْرٍ صَوْمُ الدَّهْرِ ‏","","",""],[7262,7262,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ ‏ ‏وَيَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَتَمَنَّيَنَّ أَحَدُكُمْ الْمَوْتَ إِمَّا مُحْسِنٌ ‏ ‏فَلَعَلَّهُ ‏ ‏يَزْدَادُ خَيْرًا وَإِمَّا مُسِيءٌ فَلَعَلَّهُ ‏ ‏يَسْتَعْتِبُ ‏","","",""],[7263,7263,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كَانَ رَجُلٌ يُدَايِنُ النَّاسَ فَكَانَ يَقُولُ لِفَتَاهُ إِذَا أَتَيْتَ مُعْسِرًا فَتَجَاوَزْ عَنْهُ لَعَلَّ اللَّهَ أَنْ يَتَجَاوَزَ عَنَّا قَالَ فَلَقِيَ اللَّهَ عَزَّ وَجَلَّ فَتَجَاوَزَ عَنْهُ ‏","","",""],[7264,7264,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ يَعْنِي ابْنَ سَعْدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْزِلُنَا غَدًا إِنْ شَاءَ اللَّهُ ‏ ‏بِخَيْفِ ‏ ‏بَنِي كِنَانَةَ ‏ ‏حَيْثُ ‏ ‏تَقَاسَمُوا ‏ ‏عَلَى الْكُفْرِ ‏","","",""],[7265,7265,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا رَأَيْتُمْ الْهِلَالَ فَصُومُوا وَإِذَا رَأَيْتُمُوهُ فَأَفْطِرُوا فَإِنْ ‏ ‏غُمَّ ‏ ‏عَلَيْكُمْ فَصُومُوا ثَلَاثِينَ يَوْمًا ‏","","",""],[7266,7266,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنِ ‏ ‏الْأَغَرِّ ‏ ‏وَأَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَيَعْقُوبُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَغَرَّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَلَمْ يَذْكُرْ ‏ ‏يَعْقُوبُ ‏ ‏أَبَا سَلَمَةَ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏حَدَّثَنَاه ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الْأَغَرِّ ‏ ‏وَأَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا كَانَ يَوْمُ الْجُمُعَةِ كَانَ عَلَى كُلِّ بَابٍ مِنْ أَبْوَابِ الْمَسْجِدِ مَلَائِكَةٌ يَكْتُبُونَ الْأَوَّلَ فَالْأَوَّلَ فَإِذَا جَلَسَ الْإِمَامُ ‏ ‏طَوَوْا ‏ ‏الصُّحُفَ وَجَاءُوا فَاسْتَمَعُوا الذِّكْرَ ‏","","",""],[7267,7267,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏وَيَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَكَلَ مِنْ هَذِهِ الشَّجَرَةِ فَلَا يُؤْذِينَا بِهَا فِي مَسْجِدِنَا هَذَا ‏ ‏قَالَ ‏ ‏يَعْقُوبُ ‏ ‏يَعْنِي الثُّومَ ‏","","",""],[7268,7268,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏إِبْرَاهِيمُ ‏ ‏لَا أَعْلَمُهُ إِلَّا عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَلَمْ يَشُكَّ ‏ ‏يَعْقُوبُ ‏ ‏قَالَ ‏ ‏فَضْلُ صَلَاةِ الْجَمَاعَةِ عَلَى صَلَاةِ أَحَدِكُمْ وَحْدَهُ خَمْسَةً وَعِشْرِينَ جُزْءًا ‏","","",""],[7269,7269,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ قَالَ ‏ ‏بُعِثْتُ بِجَوَامِعِ الْكَلِمِ وَنُصِرْتُ ‏ ‏بِالرُّعْبِ ‏ ‏وَبَيْنَا أَنَا نَائِمٌ أُتِيتُ بِمَفَاتِيحِ خَزَائِنِ الْأَرْضِ فَوُضِعَتْ فِي يَدِي ‏","","",""],[7270,7270,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏وَعَبْدِ الرَّحْمَنِ الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏اسْتَبَّ ‏ ‏رَجُلَانِ ‏ ‏رَجُلٌ مِنْ الْمُسْلِمِينَ ‏ ‏وَرَجُلٌ مِنْ ‏ ‏الْيَهُودِ ‏ ‏فَقَالَ الْمُسْلِمُ وَالَّذِي اصْطَفَى ‏ ‏مُحَمَّدًا ‏ ‏عَلَى الْعَالَمِينَ وَقَالَ الْيَهُودِيُّ وَالَّذِي اصْطَفَى ‏ ‏مُوسَى ‏ ‏عَلَى الْعَالَمِينَ فَغَضِبَ الْمُسْلِمُ فَلَطَمَ عَيْنَ الْيَهُودِيِّ فَأَتَى الْيَهُودِيُّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرَهُ بِذَلِكَ فَدَعَاهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَأَلَهُ فَاعْتَرَفَ بِذَلِكَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تُخَيِّرُونِي عَلَى ‏ ‏مُوسَى ‏ ‏فَإِنَّ النَّاسَ ‏ ‏يَصْعَقُونَ ‏ ‏يَوْمَ الْقِيَامَةِ فَأَكُونُ أَوَّلَ مَنْ يُفِيقُ فَأَجِدُ ‏ ‏مُوسَى ‏ ‏مُمْسِكًا بِجَانِبِ الْعَرْشِ فَمَا أَدْرِي أَكَانَ فِيمَنْ ‏ ‏صَعِقَ ‏ ‏فَأَفَاقَ قَبْلِي أَمْ كَانَ مِمَّنْ اسْتَثْنَاهُ اللَّهُ عَزَّ وَجَلَّ ‏","","",""],[7271,7271,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدٍ ‏ ‏مَوْلَى ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَنْ يُدْخِلَ أَحَدًا مِنْكُمْ عَمَلُهُ الْجَنَّةَ قَالُوا وَلَا أَنْتَ يَا رَسُولَ اللَّهِ قَالَ وَلَا أَنَا إِلَّا أَنْ ‏ ‏يَتَغَمَّدَنِي ‏ ‏اللَّهُ مِنْهُ بِفَضْلٍ وَرَحْمَةٍ ‏","","",""],[7272,7272,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏احْتَجَّ ‏ ‏آدَمُ ‏ ‏وَمُوسَى ‏ ‏عَلَيْهِمَا السَّلَام ‏ ‏فَقَالَ لَهُ ‏ ‏مُوسَى ‏ ‏أَنْتَ ‏ ‏آدَمُ ‏ ‏الَّذِي أَخْرَجَتْكَ خَطِيئَتُكَ مِنْ الْجَنَّةِ فَقَالَ لَهُ ‏ ‏آدَمُ ‏ ‏وَأَنْتَ ‏ ‏مُوسَى ‏ ‏الَّذِي اصْطَفَاكَ اللَّهُ بِكَلَامِهِ وَبِرِسَالَتِهِ تَلُومُنِي عَلَى أَمْرٍ قُدِّرَ عَلَيَّ قَبْلَ أَنْ أُخْلَقَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَحَجَّ ‏ ‏آدَمُ ‏ ‏مُوسَى ‏ ‏فَحَجَّ ‏ ‏آدَمُ ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏حَدَّثَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏حَدَّثَنِي ‏ ‏حُمَيْدُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[7273,7273,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سُئِلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّ الْأَعْمَالِ أَفْضَلُ قَالَ ‏ ‏إِيمَانٌ بِاللَّهِ وَرَسُولِهِ قَالَ ثُمَّ مَاذَا قَالَ ثُمَّ الْجِهَادُ فِي سَبِيلِ اللَّهِ قِيلَ ثُمَّ مَاذَا قَالَ ثُمَّ حَجٌّ ‏ ‏مَبْرُورٌ ‏","","",""],[7274,7274,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ يَا نِسَاءَ الْمُسْلِمَاتِ ‏ ‏لَا ‏ ‏تَحْقِرَنَّ ‏ ‏جَارَةٌ لِجَارَتِهَا وَلَوْ ‏ ‏فِرْسِنَ ‏ ‏شَاةٍ ‏","","",""],[7275,7275,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنِ ‏ ‏الْأَغَرِّ ‏ ‏وَأَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْزِلُ رَبُّنَا تَبَارَكَ اسْمُهُ كُلَّ لَيْلَةٍ حِينَ ‏ ‏يَبْقَى ثُلُثُ اللَّيْلِ الْآخِرُ إِلَى سَمَاءِ الدُّنْيَا فَيَقُولُ ‏ ‏مَنْ يَدْعُونِي فَأَسْتَجِيبَ لَهُ مَنْ يَسْأَلُنِي فَأُعْطِيَهُ مَنْ يَسْتَغْفِرُنِي ‏ ‏فَأَغْفِرَ لَهُ حَتَّى يَطْلُعَ الْفَجْرُ فَلِذَلِكَ كَانُوا يُفَضِّلُونَ صَلَاةَ آخِرِ اللَّيْلِ عَلَى صَلَاةِ أَوَّلِهِ ‏","","",""],[7276,7276,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَلَمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏أَتَيْتُ ‏ ‏سَعِيدَ ابْنَ مَرْجَانَةَ ‏ ‏فَسَأَلْتُهُ فَقَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ صَلَّى عَلَى جَنَازَةٍ فَلَمْ يَمْشِ مَعَهَا فَلْيَقُمْ حَتَّى تَغِيبَ عَنْهُ وَمَنْ مَشَى مَعَهَا فَلَا يَجْلِسْ حَتَّى تُوضَعَ ‏","","",""],[7277,7277,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَلَمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏عِرَاكِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَدْرَكَ مِنْ الصَّلَاةِ رَكْعَةً فَقَدْ أَدْرَكَهَا ‏","","",""],[7278,7278,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ أَبِي زِيَادٍ ‏ ‏حَدَّثَنِي ‏ ‏مَنْ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏أَوْصَانِي خَلِيلِي بِثَلَاثٍ وَنَهَانِي عَنْ ثَلَاثٍ ‏ ‏أَوْصَانِي ‏ ‏بِالْوِتْرِ ‏ ‏قَبْلَ النَّوْمِ وَصِيَامِ ثَلَاثَةِ أَيَّامٍ مِنْ كُلِّ شَهْرٍ وَرَكْعَتَيْ الضُّحَى قَالَ وَنَهَانِي عَنْ ‏ ‏الِالْتِفَاتِ ‏ ‏وَإِقْعَاءٍ ‏ ‏كَإِقْعَاءِ ‏ ‏الْقِرْدِ وَنَقْرٍ كَنَقْرِ الدِّيكِ ‏","","",""],[7279,7279,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْعَبَّاسِ مُحَمَّدُ بْنُ السَّمَّاكِ ‏ ‏حَدَّثَنَا ‏ ‏الْعَوَّامُ بْنُ حَوْشَبٍ ‏ ‏حَدَّثَنِي ‏ ‏مَنْ ‏ ‏سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏أَوْصَانِي خَلِيلِي ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِصَوْمِ ثَلَاثَةِ أَيَّامٍ مِنْ كُلِّ شَهْرٍ ‏ ‏وَبِالْوِتْرِ ‏ ‏قَبْلَ النَّوْمِ وَبِصَلَاةِ الضُّحَى فَإِنَّهَا صَلَاةُ ‏ ‏الْأَوَّابِينَ ‏","","",""],[7280,7280,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏ذَكْوَانَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏يَرْفَعُهُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَقُولُ اللَّهُ ‏ ‏مَنْ أَذْهَبْتُ ‏ ‏حَبِيبَتَيْهِ ‏ ‏فَصَبَرَ وَاحْتَسَبَ لَمْ أَرْضَ لَهُ بِثَوَابٍ دُونَ الْجَنَّةِ ‏","","",""],[7281,7281,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏كَعْبٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا صَلَّيْتُمْ عَلَيَّ فَاسْأَلُوا اللَّهَ لِي ‏ ‏الْوَسِيلَةَ ‏ ‏قِيلَ يَا رَسُولَ اللَّهِ وَمَا ‏ ‏الْوَسِيلَةُ ‏ ‏قَالَ أَعْلَى دَرَجَةٍ فِي الْجَنَّةِ لَا يَنَالُهَا إِلَّا رَجُلٌ وَاحِدٌ وَأَرْجُو أَنْ أَكُونَ أَنَا هُوَ ‏","","",""],[7282,7282,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَجْلَانَ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ يُحِبُّ الْعُطَاسَ وَيُبْغِضُ ‏ ‏أَوْ يَكْرَهُ ‏ ‏التَّثَاؤُبَ فَإِذَا قَالَ أَحَدُهُمْ هَا هَا فَإِنَّمَا ذَلِكَ الشَّيْطَانُ يَضْحَكُ مِنْ جَوْفِهِ ‏","","",""],[7283,7283,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُسَيَّبِ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا اسْتَيْقَظَ أَحَدُكُمْ فَلَا يُدْخِلْ يَدَهُ فِي إِنَائِهِ ‏ ‏أَوْ قَالَ فِي وَضُوئِهِ ‏ ‏حَتَّى يَغْسِلَهَا ثَلَاثَ مَرَّاتٍ فَإِنَّهُ لَا يَدْرِي أَيْنَ بَاتَتْ يَدُهُ ‏","","",""],[7284,7284,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سُئِلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الْفَأْرَةِ تَقَعُ فِي السَّمْنِ فَقَالَ ‏ ‏إِنْ كَانَ جَامِدًا فَأَلْقُوهَا وَمَا حَوْلَهَا وَإِنْ كَانَ مَائِعًا فَلَا تَقْرَبُوهُ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ بُوذَوَيْهِ ‏ ‏أَنَّ ‏ ‏مَعْمَرًا ‏ ‏كَانَ يَذْكُرُهُ ‏ ‏بِهَذَا الْإِسْنَادِ وَيَذْكُرُ قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏و قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏","","",""],[7285,7285,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَبُولَنَّ أَحَدُكُمْ فِي الْمَاءِ الدَّائِمِ ثُمَّ يَتَوَضَّأُ مِنْهُ ‏","","",""],[7286,7286,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ حَسَّانَ ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏و قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا ‏ ‏وَلَغَ ‏ ‏الْكَلْبُ فِي الْإِنَاءِ فَاغْسِلْهُ سَبْعَ مَرَّاتٍ ‏","","",""],[7287,7287,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ عَبْدِ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ عَبْدِ اللَّهِ بْنِ قَارِظٍ ‏ ‏قَالَ ‏ ‏مَرَرْتُ ‏ ‏بِأَبِي هُرَيْرَةَ ‏ ‏وَهُوَ يَتَوَضَّأُ فَقَالَ أَتَدْرِي مِمَّا أَتَوَضَّأُ مِنْ ‏ ‏أَثْوَارِ ‏ ‏أَقِطٍ ‏ ‏أَكَلْتُهَا إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏تَوَضَّئُوا مِمَّا مَسَّتْ النَّارُ ‏","","",""],[7288,7288,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏وَابْنُ جُرَيْجٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَجُلًا قَالَ يَا رَسُولَ اللَّهِ هَلْ ‏ ‏يُصَلِّي ‏ ‏الرَّجُلُ فِي الثَّوْبِ الْوَاحِدِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوَلِكُلِّكُمْ ثَوْبَانِ ‏ ‏قَالَ ‏ ‏فِي حَدِيثِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏حَدَّثَ ‏","","",""],[7289,7289,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏ذَكْوَانَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلُّ حَسَنَةٍ يَعْمَلُهَا ابْنُ ‏ ‏آدَمَ ‏ ‏تُضَاعَفُ عَشْرًا إِلَى سَبْعِ مِائَةِ ضِعْفٍ إِلَّا الصِّيَامَ فَهُوَ لِي وَأَنَا ‏ ‏أَجْزِي ‏ ‏بِهِ يَدَعُ شَهْوَتَهُ مِنْ أَجْلِي وَيَدَعُ طَعَامَهُ مِنْ أَجْلِي فَرْحَتَانِ لِلصَّائِمِ فَرْحَةٌ عِنْدَ فِطْرِهِ وَفَرْحَةٌ عِنْدَ لِقَاءِ رَبِّهِ عَزَّ وَجَلَّ ‏ ‏وَلَخُلُوفُ ‏ ‏فَمِ الصَّائِمِ أَطْيَبُ عِنْدَ اللَّهِ مِنْ رِيحِ ‏ ‏الْمِسْكِ ‏","","",""],[7290,7290,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا صَلَّى أَحَدُكُمْ فِي ثَوْبٍ فَلْيُخَالِفْ بَيْنَ طَرَفَيْهِ عَلَى ‏ ‏عَاتِقِهِ ‏","","",""],[7291,7291,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى ‏ ‏نُخَامَةً ‏ ‏فِي قِبْلَةِ الْمَسْجِدِ فَحَتَّهَا ‏ ‏بِمَرْوَةٍ ‏ ‏أَوْ بِشَيْءٍ ‏ ‏ثُمَّ قَالَ ‏ ‏إِذَا قَامَ أَحَدُكُمْ إِلَى الصَّلَاةِ فَلَا ‏ ‏يَتَنَخَّمَنَّ ‏ ‏أَمَامَهُ وَلَا عَنْ يَمِينِهِ فَإِنَّ عَنْ يَمِينِهِ مَلَكًا وَلَكِنْ ‏ ‏لِيَتَنَخَّمْ ‏ ‏عَنْ يَسَارِهِ أَوْ تَحْتَ قَدَمِهِ الْيُسْرَى ‏","","",""],[7292,7292,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَكَلَ مِنْ هَذِهِ الشَّجَرَةِ ‏ ‏يَعْنِي الثُّومَ ‏ ‏فَلَا يُؤْذِينَا فِي مَسْجِدِنَا ‏ ‏وَقَالَ ‏ ‏فِي مَوْضِعٍ آخَرَ فَلَا يَقْرَبَنَّ مَسْجِدَنَا وَلَا يُؤْذِينَا بِرِيحِ الثُّومِ ‏","","",""],[7293,7293,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏عَبَّادِ بْنِ أُنَيْسٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الْمُؤَذِّنَ يُغْفَرُ لَهُ ‏ ‏مَدَى ‏ ‏صَوْتِهِ وَيُصَدِّقُهُ كُلُّ رَطْبٍ وَيَابِسٍ سَمِعَهُ وَالشَّاهِدُ عَلَيْهِ خَمْسَةً وَعِشْرِينَ دَرَجَةً ‏","","",""],[7294,7294,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَضْلُ صَلَاةِ الْجَمْعِ عَلَى صَلَاةِ الْوَاحِدِ خَمْسٌ وَعِشْرُونَ وَتَجْتَمِعُ مَلَائِكَةُ اللَّيْلِ وَمَلَائِكَةُ النَّهَارِ فِي صَلَاةِ الصُّبْحِ ‏ ‏قَالَ ‏ ‏ثُمَّ ‏ ‏يَقُولُ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏وَاقْرَءُوا إِنْ شِئْتُمْ ‏ { ‏وَقُرْآنَ الْفَجْرِ إِنَّ قُرْآنَ الْفَجْرِ كَانَ مَشْهُودًا ‏}","","",""],[7295,7295,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏وَابْنُ جُرَيْجٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُسَيَّبِ ‏ ‏وَأَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا اشْتَدَّ الْحَرُّ فَأَبْرِدُوا عَنْ الصَّلَاةِ فَإِنَّ شِدَّةَ الْحَرِّ مِنْ ‏ ‏فَيْحِ ‏ ‏جَهَنَّمَ ‏","","",""],[7296,7296,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَزَالُ أَحَدُكُمْ فِي صَلَاةٍ مَا كَانَ يَنْتَظِرُ الصَّلَاةَ وَلَا تَزَالُ الْمَلَائِكَةُ تُصَلِّي عَلَى أَحَدِكُمْ مَا كَانَ فِي مَسْجِدٍ تَقُولُ اللَّهُمَّ اغْفِرْ لَهُ اللَّهُمَّ ارْحَمْهُ ‏","","",""],[7297,7297,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏وَالثَّوْرِيُّ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ أُمَيَّةَ ‏ ‏عَنْ ‏ ‏أَبِي عَمْرِو بْنِ حُرَيْثٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏رَفَعَهُ قَالَ ‏ ‏إِذَا صَلَّى أَحَدُكُمْ فَلْيُصَلِّ إِلَى شَيْءٍ فَإِنْ لَمْ يَكُنْ شَيْءٌ فَعَصًا فَإِنْ لَمْ يَكُنْ عَصًا فَلْيَخْطُطْ خَطًّا ثُمَّ لَا يَضُرُّهُ مَا مَرَّ بَيْنَ يَدَيْهِ ‏","","",""],[7298,7298,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ اطَّلَعَ عَلَى قَوْمٍ فِي بَيْتِهِمْ بِغَيْرِ إِذْنِهِمْ فَقَدْ حَلَّ لَهُمْ أَنْ ‏ ‏يَفْقَئُوا ‏ ‏عَيْنَهُ ‏","","",""],[7299,7299,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَبْتَدِئُوا ‏ ‏الْيَهُودَ ‏ ‏وَالنَّصَارَى ‏ ‏بِالسَّلَامِ فَإِذَا لَقِيتُمُوهُمْ فِي طَرِيقٍ فَاضْطَرُّوهُمْ إِلَى أَضْيَقِهَا ‏","","",""],[7300,7300,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا ‏ ‏طِيَرَةَ ‏ ‏وَخَيْرُهَا الْفَأْلُ قِيلَ يَا رَسُولَ اللَّهِ وَمَا الْفَأْلُ قَالَ الْكَلِمَةُ الصَّالِحَةُ يَسْمَعُهَا أَحَدُكُمْ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏طِيَرَةَ ‏ ‏وَخَيْرُهَا الْفَأْلُ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[7301,7301,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَعَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا عَدْوَى وَلَا ‏ ‏صَفَرَ ‏ ‏وَلَا ‏ ‏هَامَةَ ‏ ‏قَالَ أَعْرَابِيٌّ فَمَا بَالُ الْإِبِلِ تَكُونُ فِي الرَّمْلِ كَأَنَّهَا ‏ ‏الظِّبَاءُ ‏ ‏فَيُخَالِطُهَا الْبَعِيرُ الْأَجْرَبُ فَيُجْرِبُهَا فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمَنْ كَانَ أَعْدَى الْأَوَّلَ ‏","","",""],[7302,7302,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ اتَّخَذَ كَلْبًا إِلَّا كَلْبَ صَيْدٍ أَوْ زَرْعٍ أَوْ مَاشِيَةٍ نَقَصَ مِنْ أَجْرِهِ كُلَّ يَوْمٍ ‏ ‏قِيرَاطٌ ‏","","",""],[7303,7303,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏وَالْأَغَرُّ ‏ ‏صَاحِبُ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏أَخْبَرَهُمَا ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَنْزِلُ رَبُّنَا تَبَارَكَ وَتَعَالَى كُلَّ لَيْلَةٍ حِينَ ‏ ‏يَبْقَى ثُلُثُ اللَّيْلِ الْآخِرُ إِلَى السَّمَاءِ الدُّنْيَا فَيَقُولُ ‏ ‏مَنْ يَدْعُونِي فَأَسْتَجِيبَ لَهُ مَنْ يَسْتَغْفِرُنِي فَأَغْفِرَ لَهُ مَنْ يَسْأَلُنِي فَأُعْطِيَهُ ‏","","",""],[7304,7304,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَعَنْ ‏ ‏هَمَّامِ بْنِ مُنَبِّهٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ لِلَّهِ تِسْعَةً وَتِسْعِينَ اسْمًا مِائَةً إِلَّا وَاحِدًا مَنْ ‏ ‏أَحْصَاهَا ‏ ‏دَخَلَ الْجَنَّةَ ‏ ‏وَزَادَ فِيهِ ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهُ ‏ ‏وِتْرٌ ‏ ‏يُحِبُّ ‏ ‏الْوِتْرَ ‏","","",""],[7305,7305,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُسَيَّبِ ‏ ‏وَالْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏شَرُّ الطَّعَامِ طَعَامُ ‏ ‏الْوَلِيمَةِ ‏ ‏يُدْعَى الْغَنِيُّ وَيُتْرَكُ الْمِسْكِينُ وَهِيَ حَقٌّ وَمَنْ تَرَكَهَا فَقَدْ عَصَى ‏ ‏وَكَانَ ‏ ‏مَعْمَرٌ ‏ ‏رُبَّمَا قَالَ وَمَنْ لَمْ يُجِبْ الدَّعْوَةَ فَقَدْ عَصَى اللَّهَ وَرَسُولَهُ ‏","","",""],[7306,7306,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ إِذَا أَحَبَّ عَبْدًا قَالَ ‏ ‏لِجِبْرِيلَ ‏ ‏إِنِّي أُحِبُّ فُلَانًا فَأَحِبَّهُ قَالَ فَيَقُولُ ‏ ‏جِبْرِيلُ ‏ ‏لِأَهْلِ السَّمَاءِ إِنَّ رَبَّكُمْ يُحِبُّ فُلَانًا فَأَحِبُّوهُ قَالَ فَيُحِبُّهُ أَهْلُ السَّمَاءِ قَالَ وَيُوضَعُ لَهُ الْقَبُولُ فِي الْأَرْضِ قَالَ وَإِذَا أَبْغَضَ فَمِثْلُ ذَلِكَ ‏","","",""],[7307,7307,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلَا يُؤْذِي جَارَهُ مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيُكْرِمْ ضَيْفَهُ مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيَقُلْ خَيْرًا أَوْ لِيَصْمُتْ ‏","","",""],[7308,7308,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَاكُمْ أَهْلُ ‏ ‏الْيَمَنِ ‏ ‏هُمْ أَرَقُّ قُلُوبًا الْإِيمَانُ ‏ ‏يَمَانٍ ‏ ‏وَالْحِكْمَةُ ‏ ‏يَمَانِيَةٌ ‏ ‏وَالْفِقْهُ ‏ ‏يَمَانٍ ‏","","",""],[7309,7309,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏وَعُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏أَنَّهُمَا سَمِعَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَا أُخْبِرُكُمْ بِخَيْرِ دُورِ ‏ ‏الْأَنْصَارِ ‏ ‏قَالُوا بَلَى يَا رَسُولَ اللَّهِ قَالَ ‏ ‏بَنُو عَبْدِ الْأَشْهَلِ ‏ ‏وَهُمْ ‏ ‏رَهْطُ ‏ ‏سَعْدِ بْنِ مُعَاذٍ ‏ ‏قَالُوا ثُمَّ مَنْ يَا رَسُولَ اللَّهِ قَالَ ثُمَّ ‏ ‏بَنُو النَّجَّارِ ‏ ‏قَالُوا ثُمَّ مَنْ يَا رَسُولَ اللَّهِ قَالَ ثُمَّ ‏ ‏بَنُو الْحَارِثِ بْنِ الْخَزْرَجِ ‏ ‏قَالُوا ثُمَّ مَنْ يَا رَسُولَ اللَّهِ قَالَ ثُمَّ ‏ ‏بَنُو سَاعِدَةَ ‏ ‏قَالُوا ثُمَّ مَنْ يَا رَسُولَ اللَّهِ قَالَ ثُمَّ فِي كُلِّ دُورِ ‏ ‏الْأَنْصَارِ ‏ ‏خَيْرٌ ‏ ‏قَالَ ‏ ‏مَعْمَرٌ ‏ ‏أَخْبَرَنِي ‏ ‏ثَابِتٌ ‏ ‏وَقَتَادَةُ ‏ ‏أَنَّهُمَا سَمِعَا ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَذْكُرُ هَذَا الْحَدِيثَ إِلَّا أَنَّهُ قَالَ ‏ ‏بَنُو النَّجَّارِ ‏ ‏ثُمَّ ‏ ‏بَنُو عَبْدِ الْأَشْهَلِ ‏","","",""],[7310,7310,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏مَوْلَى ‏ ‏بَنِي جُمَحَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَا رَجُلٌ ‏ ‏يَتَبَخْتَرُ ‏ ‏فِي ‏ ‏حُلَّةٍ ‏ ‏مُعْجَبٌ ‏ ‏بِجُمَّتِهِ ‏ ‏قَدْ ‏ ‏أَسْبَلَ ‏ ‏إِزَارَهُ ‏ ‏إِذْ خَسَفَ اللَّهُ بِهِ فَهُوَ ‏ ‏يَتَجَلْجَلُ ‏ ‏أَوْ قَالَ يَهْوِي ‏ ‏فِيهَا إِلَى يَوْمِ الْقِيَامَةِ ‏","","",""],[7311,7311,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏حَدَّثَنِي ‏ ‏ثَابِتُ بْنُ قَيْسٍ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏أَخَذَتْ النَّاسَ رِيحٌ بِطَرِيقِ ‏ ‏مَكَّةَ ‏ ‏وَعُمَرُ بْنُ الْخَطَّابِ ‏ ‏حَاجٌّ فَاشْتَدَّتْ عَلَيْهِمْ فَقَالَ ‏ ‏عُمَرُ ‏ ‏لِمَنْ حَوْلَهُ مَنْ يُحَدِّثُنَا عَنْ الرِّيحِ فَلَمْ يُرْجِعُوا إِلَيْهِ شَيْئًا فَبَلَغَنِي الَّذِي سَأَلَ عَنْهُ ‏ ‏عُمَرُ ‏ ‏مِنْ ذَلِكَ ‏ ‏فَاسْتَحْثَثْتُ ‏ ‏رَاحِلَتِي حَتَّى أَدْرَكْتُهُ فَقُلْتُ يَا أَمِيرَ الْمُؤْمِنِينَ أُخْبِرْتُ أَنَّكَ سَأَلْتَ عَنْ الرِّيحِ وَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الرِّيحُ مِنْ رَوْحِ اللَّهِ تَأْتِي بِالرَّحْمَةِ ‏ ‏وَتَأْتِي بِالْعَذَابِ فَإِذَا رَأَيْتُمُوهَا فَلَا تَسُبُّوهَا وَسَلُوا اللَّهَ خَيْرَهَا وَاسْتَعِيذُوا بِهِ مِنْ شَرِّهَا ‏","","",""],[7312,7312,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُسَيَّبِ ‏ ‏وَأَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نُصِرْتُ ‏ ‏بِالرُّعْبِ ‏ ‏وَأُعْطِيتُ ‏ ‏جَوَامِعَ ‏ ‏الْكَلَامِ وَبَيْنَا أَنَا نَائِمٌ إِذْ جِيءَ بِمَفَاتِيحِ خَزَائِنِ الْأَرْضِ فَوُضِعَتْ فِي يَدَيَّ ‏ ‏فَقَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏لَقَدْ ذَهَبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنْتُمْ ‏ ‏تَنْتَثِلُونَهَا ‏","","",""],[7313,7313,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَنْفَقَ زَوْجَيْنِ مِنْ مَالِهِ فِي سَبِيلِ اللَّهِ دُعِيَ مِنْ أَبْوَابِ الْجَنَّةِ وَلِلْجَنَّةِ أَبْوَابٌ فَمَنْ كَانَ مِنْ أَهْلِ الصَّلَاةِ دُعِيَ مِنْ بَابِ الصَّلَاةِ وَمَنْ كَانَ مِنْ أَهْلِ الصَّدَقَةِ دُعِيَ مِنْ بَابِ الصَّدَقَةِ وَمَنْ كَانَ مِنْ أَهْلِ الْجِهَادِ دُعِيَ مِنْ بَابِ الْجِهَادِ وَمَنْ كَانَ مِنْ أَهْلِ الصِّيَامِ دُعِيَ مِنْ بَابِ ‏ ‏الرَّيَّانِ ‏ ‏فَقَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَاللَّهِ يَا رَسُولَ اللَّهِ مَا عَلَى أَحَدٍ مِنْ ضَرُورَةٍ مِنْ أَيِّهَا دُعِيَ فَهَلْ يُدْعَى مِنْهَا كُلِّهَا أَحَدٌ يَا رَسُولَ اللَّهِ قَالَ نَعَمْ وَإِنِّي أَرْجُو أَنْ تَكُونَ مِنْهُمْ ‏","","",""],[7314,7314,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الْعَبْدَ إِذَا تَصَدَّقَ مِنْ طَيِّبٍ تَقَبَّلَهَا اللَّهُ مِنْهُ وَأَخَذَهَا بِيَمِينِهِ وَرَبَّاهَا كَمَا يُرَبِّي أَحَدُكُمْ مُهْرَهُ أَوْ فَصِيلَهُ وَإِنَّ الرَّجُلَ لَيَتَصَدَّقُ بِاللُّقْمَةِ ‏ ‏فَتَرْبُو ‏ ‏فِي يَدِ اللَّهِ ‏ ‏أَوْ قَالَ فِي كَفِّ اللَّهِ ‏ ‏حَتَّى تَكُونَ مِثْلَ الْجَبَلِ فَتَصَدَّقُوا ‏","","",""],[7315,7315,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏احْتَجَّ ‏ ‏آدَمُ ‏ ‏وَمُوسَى ‏ ‏فَقَالَ ‏ ‏مُوسَى ‏ ‏لِآدَمَ ‏ ‏يَا ‏ ‏آدَمُ ‏ ‏أَنْتَ الَّذِي أَدْخَلْتَ ذُرِّيَّتَكَ النَّارَ فَقَالَ ‏ ‏آدَمُ ‏ ‏يَا ‏ ‏مُوسَى ‏ ‏اصْطَفَاكَ ‏ ‏اللَّهُ بِرِسَالَتِهِ وَبِكَلَامِهِ وَأَنْزَلَ عَلَيْكَ التَّوْرَاةَ فَهَلْ وَجَدْتَ أَنِّي أَهْبِطُ قَالَ نَعَمْ قَالَ ‏ ‏فَحَجَّهُ ‏ ‏آدَمُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحْوًا مِنْ حَدِيثِ ‏ ‏أَبِي سَلَمَةَ ‏","","",""],[7316,7316,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ اللَّيْثِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ أَطْفَالِ الْمُشْرِكِينَ فَقَالَ اللَّهُ أَعْلَمُ بِمَا كَانُوا عَامِلِينَ ‏","","",""],[7317,7317,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لِلشُّونِيزِ ‏ ‏عَلَيْكُمْ بِهَذِهِ الْحَبَّةِ السَّوْدَاءِ فَإِنَّ فِيهَا شِفَاءً مِنْ كُلِّ شَيْءٍ إِلَّا السَّامَ يُرِيدُ الْمَوْتَ ‏","","",""],[7318,7318,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تُفْتَحُ أَبْوَابُ الْجَنَّةِ فِي كُلِّ اثْنَيْنِ وَخَمِيسٍ ‏ ‏قَالَ ‏ ‏مَعْمَرٌ ‏ ‏وَقَالَ غَيْرُ ‏ ‏سُهَيْلٍ ‏ ‏وَتُعْرَضُ الْأَعْمَالُ فِي كُلِّ اثْنَيْنِ وَخَمِيسٍ ‏ ‏فَيَغْفِرُ اللَّهُ عَزَّ وَجَلَّ لِكُلِّ عَبْدٍ لَا يُشْرِكُ بِهِ شَيْئًا إِلَّا الْمُتَشَاحِنَيْنِ يَقُولُ اللَّهُ لِلْمَلَائِكَةِ ذَرُوهُمَا حَتَّى يَصْطَلِحَا ‏","","",""],[7319,7319,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏وَعَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ الشَّدِيدُ ‏ ‏بِالصُّرَعَةِ ‏ ‏قَالُوا فَمَنْ الشَّدِيدُ يَا رَسُولَ اللَّهِ قَالَ الَّذِي يَمْلِكُ نَفْسَهُ عِنْدَ الْغَضَبِ ‏","","",""],[7320,7320,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَأَلَ رَجُلٌ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّ الْأَعْمَالِ أَفْضَلُ قَالَ الْإِيمَانُ بِاللَّهِ قَالَ ثُمَّ مَاذَا قَالَ الْجِهَادُ فِي سَبِيلِ اللَّهِ ‏ ‏قَالَ ثُمَّ مَاذَا قَالَ ثُمَّ حَجٌّ ‏ ‏مَبْرُورٌ ‏","","",""],[7321,7321,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فِي آخِرِ الزَّمَانِ لَا تَكَادُ رُؤْيَا الْمُؤْمِنِ تَكْذِبُ وَأَصْدَقُكُمْ رُؤْيَا أَصْدَقُكُمْ حَدِيثًا وَالرُّؤْيَا ثَلَاثَةٌ الرُّؤْيَا الْحَسَنَةُ بُشْرَى مِنْ اللَّهِ عَزَّ وَجَلَّ وَالرُّؤْيَا يُحَدِّثُ بِهَا الرَّجُلُ نَفْسَهُ وَالرُّؤْيَا تَحْزِينٌ مِنْ الشَّيْطَانِ فَإِذَا رَأَى أَحَدُكُمْ رُؤْيَا يَكْرَهُهَا فَلَا يُحَدِّثْ بِهَا أَحَدًا وَلْيَقُمْ فَلْيُصَلِّ ‏ ‏قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏يُعْجِبُنِي ‏ ‏الْقَيْدُ ‏ ‏وَأَكْرَهُ ‏ ‏الْغُلَّ ‏ ‏الْقَيْدُ ‏ ‏ثَبَاتٌ فِي الدِّينِ ‏","","",""],[7322,7322,"","","‏ ‏وَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رُؤْيَا الْمُؤْمِنِ جُزْءٌ مِنْ سِتَّةٍ وَأَرْبَعِينَ جُزْءًا مِنْ النُّبُوَّةِ ‏","","",""],[7323,7323,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رُؤْيَا الْمُؤْمِنِ جُزْءٌ مِنْ سِتَّةٍ وَأَرْبَعِينَ جُزْءًا مِنْ النُّبُوَّةِ ‏","","",""],[7324,7324,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُسَيَّبِ ‏ ‏أَنَّ ‏ ‏حَسَّانَ ‏ ‏قَالَ فِي حَلْقَةٍ فِيهِمْ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏أَنْشُدُكَ ‏ ‏اللَّهَ يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏هَلْ سَمِعْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَجِبْ عَنِّي أَيَّدَكَ اللَّهُ ‏ ‏بِرُوحِ الْقُدُسِ ‏ ‏فَقَالَ اللَّهُمَّ نَعَمْ ‏","","",""],[7325,7325,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيُكْرِمْ ضَيْفَهُ ‏","","",""],[7326,7326,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏ابْنِ طَاوُسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏أُرْسِلَ مَلَكُ الْمَوْتِ إِلَى ‏ ‏مُوسَى ‏ ‏فَلَمَّا جَاءَهُ ‏ ‏صَكَّهُ ‏ ‏فَفَقَأَ ‏ ‏عَيْنَهُ فَرَجَعَ إِلَى رَبِّهِ عَزَّ وَجَلَّ فَقَالَ أَرْسَلْتَنِي إِلَى عَبْدٍ لَا يُرِيدُ الْمَوْتَ قَالَ فَرَدَّ اللَّهُ عَزَّ وَجَلَّ إِلَيْهِ عَيْنَهُ وَقَالَ ارْجِعْ إِلَيْهِ فَقُلْ لَهُ يَضَعُ يَدَهُ عَلَى ‏ ‏مَتْنِ ‏ ‏ثَوْرٍ فَلَهُ بِمَا غَطَّتْ يَدُهُ بِكُلِّ شَعْرَةٍ سَنَةٌ فَقَالَ أَيْ رَبِّ ثُمَّ ‏ ‏مَهْ ‏ ‏قَالَ ثُمَّ الْمَوْتُ قَالَ فَالْآنَ فَسَأَلَ اللَّهَ أَنْ ‏ ‏يُدْنِيَهُ ‏ ‏مِنْ الْأَرْضِ الْمُقَدَّسَةِ ‏ ‏رَمْيَةً ‏ ‏بِحَجَرٍ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَوْ كُنْتُ ثَمَّ لَأَرَيْتُكُمْ قَبْرَهُ إِلَى جَانِبِ الطَّرِيقِ تَحْتَ ‏ ‏الْكَثِيبِ الْأَحْمَرِ ‏","","",""],[7327,7327,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏لِي ‏ ‏الزُّهْرِيُّ ‏ ‏أَلَا أُحَدِّثُكَ بِحَدِيثَيْنِ عَجِيبَيْنِ ‏ ‏قَالَ ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَسْرَفَ رَجُلٌ عَلَى نَفْسِهِ فَلَمَّا حَضَرَهُ الْمَوْتُ أَوْصَى بَنِيهِ فَقَالَ إِذَا أَنَا مِتُّ فَأَحْرِقُونِي ثُمَّ اسْحَقُونِي ثُمَّ ‏ ‏اذْرُونِي ‏ ‏فِي الرِّيحِ فِي الْبَحْرِ فَوَاللَّهِ لَئِنْ قَدَرَ عَلَيَّ رَبِّي لَيُعَذِّبَنِّي عَذَابًا مَا عُذِّبَهُ أَحَدٌ قَالَ فَفَعَلُوا ذَلِكَ بِهِ فَقَالَ اللَّهُ لِلْأَرْضِ أَدِّي مَا أَخَذْتِ فَإِذَا هُوَ قَائِمٌ فَقَالَ مَا حَمَلَكَ عَلَى مَا صَنَعْتَ قَالَ خَشْيَتُكَ يَا رَبِّ ‏ ‏أَوْ مَخَافَتُكَ ‏ ‏فَغَفَرَ لَهُ بِذَلِكَ ‏","","",""],[7328,7328,"","","‏ ‏قَالَ ‏ ‏الزُّهْرِيُّ ‏ ‏وَحَدَّثَنِي ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏دَخَلَتْ امْرَأَةٌ النَّارَ فِي هِرَّةٍ رَبَطَتْهَا فَلَا هِيَ أَطْعَمَتْهَا وَلَا هِيَ أَرْسَلَتْهَا تَأْكُلُ مِنْ ‏ ‏خَشَاشِ ‏ ‏الْأَرْضِ حَتَّى مَاتَتْ ‏ ‏قَالَ ‏ ‏الزُّهْرِيُّ ‏ ‏ذَلِكَ أَنْ لَا يَتَّكِلَ رَجُلٌ وَلَا ‏ ‏يَيْأَسَ رَجُلٌ ‏","","",""],[7329,7329,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَبَّلَ ‏ ‏الْحُسَيْنَ بْنَ عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏وَالْأَقْرَعُ بْنُ حَابِسٍ التَّمِيمِيُّ ‏ ‏جَالِسٌ فَقَالَ ‏ ‏الْأَقْرَعُ ‏ ‏يَا رَسُولَ اللَّهِ إِنَّ لِي عَشَرَةً مِنْ الْوَلَدِ مَا قَبَّلْتُ إِنْسَانًا مِنْهُمْ قَطُّ قَالَ فَنَظَرَ إِلَيْهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏إِنَّ مَنْ لَا يَرْحَمُ لَا يُرْحَمُ ‏","","",""],[7330,7330,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَطَبَ ‏ ‏أُمَّ هَانِئٍ بِنْتَ أَبِي طَالِبٍ ‏ ‏فَقَالَتْ يَا رَسُولَ اللَّهِ إِنِّي قَدْ كَبِرْتُ وَلِي عِيَالٌ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَيْرُ نِسَاءٍ رَكِبْنَ نِسَاءُ ‏ ‏قُرَيْشٍ ‏ ‏أَحْنَاهُ عَلَى وَلَدٍ فِي صِغَرِهِ وَأَرْعَاهُ عَلَى زَوْجٍ فِي ذَاتِ يَدِهِ ‏ ‏قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏وَلَمْ تَرْكَبْ ‏ ‏مَرْيَمُ بِنْتُ عِمْرَانَ ‏ ‏بَعِيرًا ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏ابْنِ طَاوُسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ إِلَّا قَوْلَهُ وَلَمْ تَرْكَبْ ‏ ‏مَرْيَمُ ‏ ‏بَعِيرًا ‏","","",""],[7331,7331,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُسَيَّبِ ‏ ‏وَأَبِي سَلَمَةَ ‏ ‏أَوْ أَحَدِهِمَا ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْفَخْرُ ‏ ‏وَالْخُيَلَاءُ ‏ ‏فِي ‏ ‏الْفَدَّادِينَ ‏ ‏مِنْ أَهْلِ ‏ ‏الْوَبَرِ ‏ ‏وَالسَّكِينَةُ فِي أَهْلِ الْغَنَمِ وَالْإِيمَانُ يَمَانٍ وَالْحِكْمَةُ يَمَانِيَةٌ ‏","","",""],[7332,7332,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ لِي عَلَى ‏ ‏قُرَيْشٍ ‏ ‏حَقًّا وَإِنَّ ‏ ‏لِقُرَيْشٍ ‏ ‏عَلَيْكُمْ حَقًّا مَا حَكَمُوا فَعَدَلُوا وَأْتُمِنُوا فَأَدَّوْا وَاسْتُرْحِمُوا فَرَحِمُوا ‏","","",""],[7333,7333,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَسَمَّوْا بِاسْمِي وَلَا تَكَنَّوْا بِكُنْيَتِي ‏","","",""],[7334,7334,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏هَمَّامٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نِعِمَّا لِلْعَبْدِ أَنْ يَتَوَفَّاهُ اللَّهُ بِحُسْنِ عِبَادَةِ رَبِّهِ وَبِطَاعَةِ سَيِّدِهِ نِعِمَّا لَهُ وَنِعِمَّا لَهُ ‏","","",""],[7335,7335,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏أَخْبَرَنِي ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَطَاعَنِي فَقَدْ أَطَاعَ اللَّهَ وَمَنْ عَصَانِي فَقَدْ عَصَى اللَّهَ وَمَنْ أَطَاعَ أَمِيرِي فَقَدْ أَطَاعَنِي وَمَنْ عَصَى أَمِيرِي فَقَدْ عَصَانِي ‏","","",""],[7336,7336,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏يُصَلِّي بِنَا فَيُكَبِّرُ حِينَ يَقُومُ وَحِينَ يَرْكَعُ وَإِذَا أَرَادَ أَنْ يَسْجُدَ بَعْدَمَا يَرْفَعُ مِنْ الرُّكُوعِ وَإِذَا أَرَادَ أَنْ يَسْجُدَ بَعْدَمَا يَرْفَعُ مِنْ السُّجُودِ وَإِذَا جَلَسَ وَإِذَا أَرَادَ أَنْ يَرْفَعَ فِي الرَّكْعَتَيْنِ كَبَّرَ وَيُكَبِّرُ مِثْلَ ذَلِكَ فِي الرَّكْعَتَيْنِ الْأُخْرَيَيْنِ فَإِذَا سَلَّمَ قَالَ وَالَّذِي نَفْسِي بِيَدِهِ إِنِّي لَأَقْرَبُكُمْ شَبَهًا بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَعْنِي صَلَاتَهُ ‏ ‏مَا زَالَتْ هَذِهِ صَلَاتُهُ حَتَّى فَارَقَ الدُّنْيَا ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ بْنِ هِشَامٍ ‏ ‏وَعَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّهُمَا صَلَّيَا خَلْفَ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏فَذَكَرَا نَحْوَ حَدِيثِ ‏ ‏عَبْدِ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قَامَ إِلَى الصَّلَاةِ يُكَبِّرُ ‏ ‏فَذَكَرَ نَحْوَهُ ‏","","",""],[7337,7337,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا قَالَ الْإِمَامُ ‏ { ‏غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ ‏} ‏فَقُولُوا آمِينَ فَإِنَّ الْمَلَائِكَةَ يَقُولُونَ آمِينَ وَإِنَّ الْإِمَامَ يَقُولُ آمِينَ فَمَنْ وَافَقَ تَأْمِينُهُ تَأْمِينَ الْمَلَائِكَةِ غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ ‏","","",""],[7338,7338,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمَّا رَفَعَ رَأْسَهُ مِنْ الرُّكُوعِ قَالَ ‏ ‏اللَّهُمَّ رَبَّنَا وَلَكَ الْحَمْدُ ‏","","",""],[7339,7339,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏قَالَ ‏ ‏الزُّهْرِيُّ ‏ ‏وَقَدْ ‏ ‏أَخْبَرَنِي ‏ ‏سَعِيدُ بْنُ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا أُقِيمَتْ الصَّلَاةُ فَلَا تَأْتُوهَا تَسْعَوْنَ وَلَكِنْ ائْتُوهَا وَأَنْتُمْ تَمْشُونَ وَعَلَيْكُمْ ‏ ‏السَّكِينَةُ ‏ ‏فَمَا أَدْرَكْتُمْ فَصَلُّوا وَمَا فَاتَكُمْ فَأَتِمُّوا ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ يَعْنِي ابْنَ الْهَادِ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ إِذَا أُقِيمَتْ الصَّلَاةُ ‏ ‏فَذَكَرَهُ ‏","","",""],[7340,7340,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا أَدْرَكْتُمْ فَصَلُّوا وَمَا فَاتَكُمْ فَاقْضُوا ‏ ‏قَالَ ‏ ‏مَعْمَرٌ ‏ ‏وَلَمْ يَذْكُرْ سُجُودًا ‏","","",""],[7341,7341,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ أَدْرَكَ رَكْعَةً مِنْ الصَّلَاةِ فَقَدْ أَدْرَكَ الصَّلَاةَ ‏","","",""],[7342,7342,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏وَأَبِي بَكْرِ بْنِ سُلَيْمَانَ بْنِ أَبِي حَثْمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الظُّهْرَ ‏ ‏أَوْ الْعَصْرَ ‏ ‏فَسَلَّمَ فِي رَكْعَتَيْنِ فَقَالَ لَهُ ‏ ‏ذُو الشِّمَالَيْنِ بْنُ عَبْدِ عَمْرٍو ‏ ‏وَكَانَ حَلِيفًا ‏ ‏لِبَنِي زُهْرَةَ ‏ ‏أَخُفِّفَتْ الصَّلَاةُ أَمْ نَسِيتَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا يَقُولُ ‏ ‏ذُو الْيَدَيْنِ ‏ ‏قَالُوا صَدَقَ يَا نَبِيَّ اللَّهِ ‏ ‏فَأَتَمَّ بِهِمْ الرَّكْعَتَيْنِ اللَّتَيْنِ نَقَصَ ‏","","",""],[7343,7343,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُسَيَّبِ ‏ ‏وَأَبِي سَلَمَةَ ‏ ‏أَوْ أَحَدِهِمَا ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا صَلَّى أَحَدُكُمْ بِالنَّاسِ فَلْيُخَفِّفْ فَإِنَّ فِيهِمْ الضَّعِيفَ وَالشَّيْخَ الْكَبِيرَ وَذَا الْحَاجَةِ ‏","","",""],[7344,7344,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا يُؤْمِنُ الَّذِي يَرْفَعُ رَأْسَهُ قَبْلَ الْإِمَامِ أَنْ يَرُدَّ اللَّهُ رَأْسَهُ رَأْسَ حِمَارٍ ‏","","",""],[7345,7345,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏لَمَّا رَفَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأْسَهُ مِنْ الرَّكْعَةِ الْآخِرَةِ فِي صَلَاةِ الْفَجْرِ قَالَ ‏ ‏اللَّهُمَّ رَبَّنَا وَلَكَ الْحَمْدُ أَنْجِ ‏ ‏الْوَلِيدَ ‏ ‏وَسَلَمَةَ بْنَ هِشَامٍ ‏ ‏وَعَيَّاشَ بْنَ أَبِي رَبِيعَةَ ‏ ‏وَالْمُسْتَضْعَفِينَ مِنْ الْمُؤْمِنِينَ اللَّهُمَّ اشْدُدْ ‏ ‏وَطْأَتَكَ ‏ ‏عَلَى ‏ ‏مُضَرَ ‏ ‏وَاجْعَلْهَا عَلَيْهِمْ ‏ ‏كَسِنِي ‏ ‏يُوسُفَ ‏","","",""],[7346,7346,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا أَذِنَ اللَّهُ لِشَيْءٍ مَا أَذِنَ لِنَبِيٍّ أَنْ يَتَغَنَّى بِالْقُرْآنِ ‏","","",""],[7347,7347,"","","‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏أَوْصَانِي النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِثَلَاثٍ لَسْتُ بِتَارِكِهِنَّ فِي حَضَرٍ وَلَا سَفَرٍ ‏ ‏نَوْمٍ عَلَى ‏ ‏وِتْرٍ ‏ ‏وَصِيَامِ ثَلَاثَةِ أَيَّامٍ مِنْ كُلِّ شَهْرٍ وَرَكْعَتَيْ الضُّحَى ‏ ‏قَالَ ‏ ‏ثُمَّ أَوْهَمَ ‏ ‏الْحَسَنُ ‏ ‏فَجَعَلَ مَكَانَ الضُّحَى غُسْلَ يَوْمِ الْجُمُعَةِ ‏","","",""],[7348,7348,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏زِيَادٌ يَعْنِي ابْنَ سَعْدٍ ‏ ‏أَنَّ ‏ ‏ثَابِتَ بْنَ عِيَاضٍ ‏ ‏مَوْلَى ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ زَيْدٍ ‏ ‏أَخْبَرَهُ أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ‏ ‏وَلَغَ ‏ ‏الْكَلْبُ فِي إِنَاءِ أَحَدِكُمْ فَلْيَغْسِلْهُ سَبْعَ مَرَّاتٍ ‏ ‏قَالَ ‏ ‏وَأَخْبَرَنِي ‏ ‏أَيْضًا ‏ ‏أَنَّهُ أَخْبَرَهُ ‏ ‏هِلَالُ بْنُ أُسَامَةَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا سَلَمَةَ ‏ ‏يُخْبِرُ بِذَلِكَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[7349,7349,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏زِيَادٌ ‏ ‏أَنَّ ‏ ‏ثَابِتًا ‏ ‏مَوْلَى ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ زَيْدٍ ‏ ‏وَقَالَ ‏ ‏ابْنُ بَكْرٍ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا كَانَ أَحَدُكُمْ نَائِمًا ثُمَّ اسْتَيْقَظَ فَأَرَادَ الْوُضُوءَ فَلَا يَضَعْ يَدَهُ فِي الْإِنَاءِ حَتَّى يَصُبَّ عَلَى يَدِهِ فَإِنَّهُ لَا يَدْرِي أَيْنَ بَاتَتْ يَدُهُ ‏","","",""],[7350,7350,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏أَخْبَرَنِي ‏ ‏عُمَرُ بْنُ عَبْدِ الْعَزِيزِ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ إِبْرَاهِيمَ بْنِ قَارِظٍ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّهُ وَجَدَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَتَوَضَّأُ عَلَى ظَهْرِ الْمَسْجِدِ فَقَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏إِنَّمَا أَتَوَضَّأُ مِنْ ‏ ‏أَثْوَارِ ‏ ‏أَقِطٍ ‏ ‏أَكَلْتُهَا لِأَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَوَضَّئُوا مِمَّا مَسَّتْ النَّارُ ‏","","",""],[7351,7351,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى يُقَاتِلَكُمْ قَوْمٌ يَنْتَعِلُونَ الشَّعْرَ وُجُوهُهُمْ ‏ ‏كَالْمَجَانِّ ‏ ‏الْمُطْرَقَةِ ‏","","",""],[7352,7352,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى تَضْطَرِبَ ‏ ‏أَلْيَاتُ ‏ ‏نِسَاءِ ‏ ‏دَوْسٍ ‏ ‏حَوْلَ ‏ ‏ذِي الْخَلَصَةِ ‏ ‏وَكَانَتْ صَنَمًا يَعْبُدُهَا ‏ ‏دَوْسٌ ‏ ‏فِي الْجَاهِلِيَّةِ ‏ ‏بِتَبَالَةَ ‏","","",""],[7353,7353,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَذْهَبُ ‏ ‏كِسْرَى ‏ ‏فَلَا يَكُونُ ‏ ‏كِسْرَى ‏ ‏بَعْدَهُ وَيَذْهَبُ ‏ ‏قَيْصَرُ ‏ ‏فَلَا يَكُونُ ‏ ‏قَيْصَرُ ‏ ‏بَعْدَهُ وَالَّذِي نَفْسِي بِيَدِهِ لَتُنْفِقُنَّ كُنُوزَهُمَا فِي سَبِيلِ اللَّهِ تَعَالَى ‏","","",""],[7354,7354,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُسَيَّبِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏لَيُوشِكُ أَنْ يَنْزِلَ فِيكُمْ ‏ ‏ابْنُ مَرْيَمَ ‏ ‏حَكَمًا عَادِلًا وَإِمَامًا مُقْسِطًا يَكْسِرُ الصَّلِيبَ وَيَقْتُلُ الْخِنْزِيرَ وَيَضَعُ الْجِزْيَةَ وَيَفِيضُ الْمَالُ حَتَّى لَا يَقْبَلَهَا أَحَدٌ ‏","","",""],[7355,7355,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏مَوْلَى ‏ ‏أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَيْفَ بِكُمْ إِذَا نَزَلَ بِكُمْ ‏ ‏ابْنُ مَرْيَمَ ‏ ‏فَأَمَّكُمْ ‏ ‏أَوْ قَالَ إِمَامُكُمْ مِنْكُمْ ‏","","",""],[7356,7356,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏حَنْظَلَةَ الْأَسْلَمِيِّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏لَيُهِلَّنَّ ‏ ‏ابْنُ مَرْيَمَ ‏ ‏مِنْ ‏ ‏فَجِّ ‏ ‏الرَّوْحَاءِ ‏ ‏بِالْحَجِّ أَوْ الْعُمْرَةِ أَوْ ‏ ‏لَيُثَنِّيَهُمَا ‏","","",""],[7357,7357,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَسُبُّ أَحَدُكُمْ الدَّهْرَ فَإِنَّ اللَّهَ هُوَ الدَّهْرُ وَلَا يَقُولَنَّ أَحَدُكُمْ لِلْعِنَبِ الْكَرْمَ فَإِنَّ الْكَرْمَ هُوَ الرَّجُلُ الْمُسْلِمُ ‏","","",""],[7358,7358,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ اللَّهُ عَزَّ وَجَلَّ ‏ ‏يُؤْذِينِي ابْنُ ‏ ‏آدَمَ ‏ ‏قَالَ يَقُولُ يَا ‏ ‏خَيْبَةَ ‏ ‏الدَّهْرِ فَإِنِّي أَنَا الدَّهْرُ أُقَلِّبُ لَيْلَهُ وَنَهَارَهُ فَإِنْ شِئْتُ قَبَضْتُهُمَا ‏","","",""],[7359,7359,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنِ ‏ ‏الْحَارِثِ بْنِ مُخَلَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الَّذِي يَأْتِي امْرَأَتَهُ فِي ‏ ‏دُبُرِهَا ‏ ‏لَا يَنْظُرُ اللَّهُ إِلَيْهِ ‏","","",""],[7360,7360,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏سُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا سَمِعْتُمْ رَجُلًا يَقُولُ قَدْ هَلَكَ النَّاسُ فَهُوَ أَهْلَكُهُمْ يَقُولُ اللَّهُ إِنَّهُ هُوَ هَالِكٌ ‏","","",""],[7361,7361,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ عَبْدِ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ عَبْدِ اللَّهِ بْنِ قَارِظٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَعَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا قُلْتَ لِصَاحِبِكَ أَنْصِتْ وَالْإِمَامُ يَخْطُبُ يَوْمَ الْجُمُعَةِ فَقَدْ ‏ ‏لَغَوْتَ ‏ ‏قَالَ ‏ ‏ابْنُ بَكْرٍ ‏ ‏فِي حَدِيثِهِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏حَدِيثِ ‏ ‏عُمَرَ بْنِ عَبْدِ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ عَبْدِ اللَّهِ بْنِ قَارِظٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏و عَنْ ‏ ‏حَدِيثِ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهُ قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُهُ ‏","","",""],[7362,7362,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏الْعَلَاءُ بْنُ عَبْدِ الرَّحْمَنِ بْنِ يَعْقُوبَ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ اللَّهِ إِسْحَاقَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَطْلُعُ الشَّمْسُ وَلَا تَغْرُبُ عَلَى يَوْمٍ أَفْضَلَ مِنْ يَوْمِ الْجُمُعَةِ وَمَا مِنْ دَابَّةٍ إِلَّا تَفْزَعُ لِيَوْمِ الْجُمُعَةِ إِلَّا هَذَيْنِ ‏ ‏الثَّقَلَيْنِ ‏ ‏مِنْ الْجِنِّ وَالْإِنْسِ عَلَى كُلِّ بَابٍ مِنْ أَبْوَابِ الْمَسْجِدِ مَلَكَانِ يَكْتُبَانِ الْأَوَّلَ فَالْأَوَّلَ فَكَرَجُلٍ قَدَّمَ ‏ ‏بَدَنَةً ‏ ‏وَكَرَجُلٍ قَدَّمَ بَقَرَةً وَكَرَجُلٍ قَدَّمَ شَاةً وَكَرَجُلٍ قَدَّمَ طَائِرًا وَكَرَجُلٍ قَدَّمَ بَيْضَةً فَإِذَا قَعَدَ الْإِمَامُ طُوِيَتْ الصُّحُفُ ‏","","",""],[7363,7363,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏حَدَّثَنِي ‏ ‏الْعَبَّاسُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ مَسْلَمَةَ الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏وَأَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ فِي الْجُمُعَةِ سَاعَةً لَا يُوَافِقُهَا عَبْدٌ مُسْلِمٌ يَسْأَلُ اللَّهَ عَزَّ وَجَلَّ فِيهَا خَيْرًا إِلَّا أَعْطَاهُ إِيَّاهُ وَهِيَ بَعْدَ الْعَصْرِ ‏","","",""],[7364,7364,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏حَدَّثَنِي ‏ ‏سُهَيْلُ بْنُ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مِنْ غُسْلِهَا الْغُسْلُ وَمِنْ حَمْلِهَا الْوُضُوءُ ‏","","",""],[7365,7365,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏الْحَارِثُ بْنُ عَبْدِ الْمُطَّلِبِ ‏ ‏وَقَالَ ‏ ‏ابْنُ بَكْرٍ ‏ ‏ابْنُ عَبْدِ الْمَلِكِ ‏ ‏أَنَّ ‏ ‏نَافِعَ بْنَ جُبَيْرٍ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّهُ سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ صَلَّى عَلَى جَنَازَةٍ فَاتَّبَعَهَا فَلَهُ ‏ ‏قِيرَاطَانِ ‏ ‏مِثْلَيْ ‏ ‏أُحُدٍ ‏ ‏وَمَنْ صَلَّى وَلَمْ يَتْبَعْهَا فَلَهُ ‏ ‏قِيرَاطٌ ‏ ‏مِثْلُ ‏ ‏أُحُدٍ ‏ ‏قَالَ ‏ ‏ابْنُ بَكْرٍ ‏ ‏الْقِيرَاطُ ‏ ‏مِثْلُ ‏ ‏أُحُدٍ ‏","","",""],[7366,7366,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏وَهْبِ بْنِ كَيْسَانَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏أَنَّهُ أَخْبَرَهُ ‏ ‏أَنَّ ‏ ‏سَلَمَةَ بْنَ الْأَزْرَقِ ‏ ‏كَانَ جَالِسًا مَعَ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏بِالسُّوقِ فَمُرَّ بِجِنَازَةٍ ‏ ‏يُبْكَى عَلَيْهَا فَعَابَ ذَلِكَ ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏فَانْتَهَرَهُنَّ فَقَالَ لَهُ ‏ ‏سَلَمَةُ بْنُ الْأَزْرَقِ ‏ ‏لَا تَقُلْ ذَلِكَ فَأَشْهَدُ عَلَى ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏لَسَمِعْتُهُ يَقُولُ وَتُوُفِّيَتْ امْرَأَةٌ مِنْ ‏ ‏كَنَائِنِ ‏ ‏مَرْوَانَ ‏ ‏وَشَهِدَهَا وَأَمَرَ ‏ ‏مَرْوَانُ ‏ ‏بِالنِّسَاءِ اللَّاتِي يَبْكِينَ يُطْرَدْنَ فَقَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏دَعْهُنَّ يَا ‏ ‏أَبَا عَبْدِ الْمَلِكِ ‏ ‏فَإِنَّهُ مُرَّ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِجِنَازَةٍ ‏ ‏يُبْكَى عَلَيْهَا وَأَنَا مَعَهُ وَمَعَهُ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏فَانْتَهَرَ ‏ ‏عُمَرُ ‏ ‏اللَّاتِي يَبْكِينَ مَعَ الْجِنَازَةِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَعْهُنَّ يَا ‏ ‏ابْنَ الْخَطَّابِ ‏ ‏فَإِنَّ النَّفْسَ مُصَابَةٌ وَإِنَّ الْعَيْنَ دَامِعَةٌ وَإِنَّ الْعَهْدَ حَدِيثٌ ‏ ‏قَالَ ‏ ‏أَنْتَ سَمِعْتَهُ قَالَ نَعَمْ قَالَ ‏ ‏فَاللَّهُ وَرَسُولُهُ أَعْلَمُ ‏","","",""],[7367,7367,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ ‏ ‏رَجُلًا ‏ ‏أَفْطَرَ فِي رَمَضَانَ أَنْ يُعْتِقَ رَقَبَةً أَوْ يَصُومَ شَهْرَيْنِ أَوْ يُطْعِمَ سِتِّينَ مِسْكِينًا ‏","","",""],[7368,7368,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَطَاءٌ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ الزَّيَّاتِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلُّ عَمَلِ ابْنِ ‏ ‏آدَمَ ‏ ‏لَهُ إِلَّا الصِّيَامَ فَإِنَّهُ لِي وَأَنَا أَجْزِي بِهِ وَالصِّيَامُ ‏ ‏جُنَّةٌ ‏ ‏وَإِذَا كَانَ يَوْمُ صَوْمِ أَحَدِكُمْ فَلَا ‏ ‏يَرْفُثْ ‏ ‏يَوْمَئِذٍ وَلَا ‏ ‏يَصْخَبْ ‏ ‏فَإِنْ شَاتَمَهُ أَحَدٌ أَوْ قَاتَلَهُ فَلْيَقُلْ إِنِّي امْرُؤٌ صَائِمٌ مَرَّتَيْنِ وَالَّذِي نَفْسُ ‏ ‏مُحَمَّدٍ ‏ ‏بِيَدِهِ ‏ ‏لَخُلُوفُ ‏ ‏فَمِ الصَّائِمِ أَطْيَبُ عِنْدَ اللَّهِ يَوْمَ الْقِيَامَةِ مِنْ رِيحِ ‏ ‏الْمِسْكِ ‏ ‏وَلِلصَّائِمِ فَرْحَتَانِ يَفْرَحُهُمَا إِذَا أَفْطَرَ فَرِحَ بِفِطْرِهِ وَإِذَا لَقِيَ رَبَّهُ عَزَّ وَجَلَّ فَرِحَ بِصِيَامِهِ ‏","","",""],[7369,7369,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهُ قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْتِي أَحَدَكُمْ الشَّيْطَانُ وَهُوَ فِي صَلَاتِهِ فَيَلْبِسُ عَلَيْهِ حَتَّى لَا يَدْرِيَ كَمْ صَلَّى فَإِذَا وَجَدَ ذَلِكَ فَلْيَسْجُدْ سَجْدَتَيْنِ وَهُوَ جَالِسٌ ‏","","",""],[7370,7370,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏عُمَرُ بْنُ عَطَاءِ بْنِ أَبِي الْخُوَارِ ‏ ‏أَنَّهُ ‏ ‏بَيْنَمَا هُوَ جَالِسٌ مَعَ ‏ ‏نَافِعِ بْنِ جُبَيْرٍ ‏ ‏إِذْ مَرَّ بِهِمَا ‏ ‏أَبُو عَبْدِ اللَّهِ ‏ ‏خَتَنُ ‏ ‏زَيْدِ بْنِ الرَّيَّانِ ‏ ‏وَقَالَ ‏ ‏ابْنُ بَكْرٍ ‏ ‏ابْنِ الزَّبَّانِ ‏ ‏فَدَعَاهُ ‏ ‏نَافِعٌ ‏ ‏فَقَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةٌ مَعَ الْإِمَامِ أَفْضَلُ مِنْ خَمْسَةٍ وَعِشْرِينَ صَلَاةً يُصَلِّيهَا وَحْدَهُ ‏","","",""],[7371,7371,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَطَاءٌ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يُخْبِرُهُمْ ‏ ‏فِي كُلِّ صَلَاةٍ يُقْرَأُ فَمَا أَسْمَعَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَسْمَعْنَاكُمْ وَمَا أَخْفَى عَلَيْنَا أَخْفَيْنَا عَلَيْكُمْ ‏ ‏قَالَ ‏ ‏ابْنُ بَكْرٍ ‏ ‏فِي كُلِّ صَلَاةٍ قُرْآنٌ ‏","","",""],[7372,7372,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏لَا أَعْلَمُهُ إِلَّا ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يُمْنَعُ فَضْلُ مَاءٍ لِيُمْنَعَ بِهِ ‏ ‏فَضْلُ ‏ ‏الْكَلَإِ ‏","","",""],[7373,7373,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ اشْتَرَى شَاةً ‏ ‏مُصَرَّاةً ‏ ‏فَإِنَّهُ يَحْلُبُهَا فَإِنْ رَضِيَهَا أَخَذَهَا وَإِلَّا رَدَّهَا وَرَدَّ مَعَهَا ‏ ‏صَاعًا ‏ ‏مِنْ تَمْرٍ ‏","","",""],[7374,7374,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو كَثِيرٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا بَاعَ أَحَدُكُمْ الشَّاةَ أَوْ ‏ ‏اللَّقْحَةَ ‏ ‏فَلَا ‏ ‏يُحَفِّلْهَا ‏","","",""],[7375,7375,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَبِيعُ حَاضِرٌ ‏ ‏لِبَادٍ ‏ ‏وَلَا ‏ ‏تَنَاجَشُوا ‏ ‏وَلَا يَزِيدُ الرَّجُلُ عَلَى بَيْعِ أَخِيهِ وَلَا يَخْطُبُ عَلَى خِطْبَتِهِ وَلَا تَسْأَلُ امْرَأَةٌ طَلَاقَ أُخْتِهَا ‏","","",""],[7376,7376,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ وَاسِعٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ وَسَّعَ عَلَى ‏ ‏مَكْرُوبٍ ‏ ‏كُرْبَةً ‏ ‏فِي الدُّنْيَا وَسَّعَ اللَّهُ عَلَيْهِ ‏ ‏كُرْبَةً ‏ ‏فِي الْآخِرَةِ وَمَنْ سَتَرَ عَوْرَةَ مُسْلِمٍ فِي الدُّنْيَا سَتَرَ اللَّهُ عَوْرَتَهُ فِي الْآخِرَةِ وَاللَّهُ فِي عَوْنِ الْمَرْءِ مَا كَانَ فِي عَوْنِ أَخِيهِ ‏","","",""],[7377,7377,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ هُرْمُزَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَمْنَعَنَّ أَحَدُكُمْ جَارَهُ أَنْ يَضَعَ خَشَبَةً عَلَى جِدَارِهِ ‏ ‏ثُمَّ يَقُولُ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏مَالِي أَرَاكُمْ مُعْرِضِينَ وَاللَّهِ لَأَرْمِيَنَّ بِهَا بَيْنَ أَكْتَافِكُمْ ‏","","",""],[7378,7378,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏اقْتَتَلَتْ ‏ ‏امْرَأَتَانِ مِنْ ‏ ‏هُذَيْلٍ ‏ ‏فَرَمَتْ إِحْدَاهُمَا الْأُخْرَى بِحَجَرٍ فَأَصَابَتْ بَطْنَهَا فَقَتَلَتْهَا وَأَلْقَتْ جَنِينًا ‏ ‏فَقَضَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِدِيَتِهَا ‏ ‏عَلَى ‏ ‏الْعَاقِلَةِ ‏ ‏وَفِي جَنِينِهَا ‏ ‏غُرَّةٌ ‏ ‏عَبْدٌ أَوْ أَمَةٌ فَقَالَ قَائِلٌ كَيْفَ ‏ ‏يُعْقَلُ ‏ ‏مَنْ لَا أَكَلَ وَلَا شَرِبَ وَلَا نَطَقَ وَلَا ‏ ‏اسْتَهَلَّ ‏ ‏فَمِثْلُ ذَلِكَ يُطَلُّ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَمَا زَعَمَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏هَذَا مِنْ إِخْوَانِ ‏ ‏الْكُهَّانِ ‏","","",""],[7379,7379,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏وَأَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْعَجْمَاءُ ‏ ‏جُبَارٌ ‏ ‏وَالْبِئْرُ ‏ ‏جُبَارٌ ‏ ‏وَالْمَعْدِنُ ‏ ‏جُبَارٌ ‏ ‏وَفِي ‏ ‏الرِّكَازِ ‏ ‏الْخُمُسُ ‏ ‏وَالْجُبَارُ الْهَدَرُ ‏","","",""],[7380,7380,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏قَالَ قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏إِنَّكُمْ تَقُولُونَ أَكْثَرَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاللَّهُ الْمُوعِدُ إِنَّكُمْ تَقُولُونَ مَا بَالُ ‏ ‏الْمُهَاجِرِينَ ‏ ‏لَا يُحَدِّثُونَ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِهَذِهِ الْأَحَادِيثِ وَمَا بَالُ ‏ ‏الْأَنْصَارِ ‏ ‏لَا يُحَدِّثُونَ بِهَذِهِ الْأَحَادِيثِ وَإِنَّ أَصْحَابِي مِنْ ‏ ‏الْمُهَاجِرِينَ ‏ ‏كَانَتْ تَشْغَلُهُمْ صَفَقَاتُهُمْ فِي الْأَسْوَاقِ وَإِنَّ أَصْحَابِي مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏كَانَتْ تَشْغَلُهُمْ أَرْضُوهُمْ وَالْقِيَامُ عَلَيْهَا وَإِنِّي كُنْتُ امْرَأً مُعْتَكِفًا وَكُنْتُ أُكْثِرُ مُجَالَسَةَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَحْضُرُ إِذَا غَابُوا وَأَحْفَظُ إِذَا نَسُوا وَإِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدَّثَنَا يَوْمًا فَقَالَ ‏ ‏مَنْ يَبْسُطُ ثَوْبَهُ حَتَّى أَفْرُغَ مِنْ حَدِيثِي ثُمَّ يَقْبِضُهُ إِلَيْهِ فَإِنَّهُ لَيْسَ ‏ ‏يَنْسَى شَيْئًا سَمِعَهُ مِنِّي أَبَدًا فَبَسَطْتُ ثَوْبِي ‏ ‏أَوْ قَالَ نَمِرَتِي ‏ ‏ثُمَّ قَبَضْتُهُ إِلَيَّ ‏ ‏فَوَاللَّهِ مَا نَسِيتُ شَيْئًا سَمِعْتُهُ مِنْهُ وَايْمُ اللَّهِ لَوْلَا آيَةٌ فِي كِتَابِ اللَّهِ مَا حَدَّثْتُكُمْ بِشَيْءٍ أَبَدًا ثُمَّ تَلَا ‏ { ‏إِنَّ الَّذِينَ يَكْتُمُونَ مَا أَنْزَلْنَا مِنْ الْبَيِّنَاتِ وَالْهُدَى ‏} ‏الْآيَةَ كُلَّهَا ‏","","",""],[7381,7381,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحْنُ الْآخِرُونَ الْأَوَّلُونَ يَوْمَ الْقِيَامَةِ نَحْنُ أَوَّلُ النَّاسِ دُخُولًا الْجَنَّةَ بَيْدَ أَنَّهُمْ أُوتُوا الْكِتَابَ مِنْ قَبْلِنَا وَأُوتِينَاهُ مِنْ بَعْدِهِمْ فَهَدَانَا اللَّهُ لِمَا اخْتَلَفُوا فِيهِ مِنْ الْحَقِّ بِإِذْنِهِ فَهَذَا الْيَوْمُ الَّذِي هَدَانَا اللَّهُ لَهُ وَالنَّاسُ لَنَا فِيهِ تَبَعٌ غَدًا ‏ ‏لِلْيَهُوَدِ ‏ ‏وَبَعْدَ غَدٍ ‏ ‏لِلنَّصَارَى ‏","","",""],[7382,7382,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏ابْنِ طَاوُسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَعَنْ ‏ ‏هَمَّامِ بْنِ مُنَبِّهٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحْنُ الْآخِرُونَ السَّابِقُونَ يَوْمَ الْقِيَامَةِ بَيْدَ أَنَّهُمْ أُوتُوا الْكِتَابَ مِنْ قَبْلِنَا وَأُوتِينَاهُ مِنْ بَعْدِهِمْ فَهَذَا يَوْمُهُمْ الَّذِي فُرِضَ عَلَيْهِمْ فَاخْتَلَفُوا فِيهِ فَهَدَانَا اللَّهُ لَهُ فَهُمْ لَنَا فِيهِ تَبَعٌ ‏ ‏فَالْيَهُودُ ‏ ‏غَدًا ‏ ‏وَالنَّصَارَى ‏ ‏بَعْدَ غَدٍ ‏","","",""],[7383,7383,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا مِنْ مَوْلُودٍ إِلَّا الشَّيْطَانُ يَمَسُّهُ حِينَ يُولَدُ فَيَسْتَهِلُّ صَارِخًا مِنْ مَسَّةِ الشَّيْطَانِ إِيَّاهُ ‏ ‏إِلَّا ‏ ‏مَرْيَمَ ‏ ‏وَابْنَهَا ‏ ‏ثُمَّ ‏ ‏يَقُولُ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏اقْرَءُوا إِنْ شِئْتُمْ ‏ { ‏وَإِنِّي أُعِيذُهَا بِكَ وَذُرِّيَّتَهَا مِنْ الشَّيْطَانِ الرَّجِيمِ ‏}","","",""],[7384,7384,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُسَيَّبِ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏يُحَدِّثُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏خَيْرُ نِسَاءٍ رَكِبْنَ الْإِبِلَ ‏ ‏صُلَّحُ نِسَاءِ ‏ ‏قُرَيْشٍ ‏ ‏أَحْنَاهُ عَلَى وَلَدٍ فِي صِغَرِهِ وَأَرْعَاهُ لِزَوْجٍ فِي ذَاتِ يَدِهِ ‏ ‏قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏وَلَمْ تَرْكَبْ ‏ ‏مَرْيَمُ ‏ ‏بَعِيرًا قَطُّ ‏","","",""],[7385,7385,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَيْتُ ‏ ‏عَمْرَو بْنَ عَامِرٍ الْخُزَاعِيَّ ‏ ‏يَجُرُّ قُصْبَهُ ‏ ‏يَعْنِي الْأَمْعَاءَ ‏ ‏فِي النَّارِ وَهُوَ أَوَّلُ مَنْ ‏ ‏سَيَّبَ ‏ ‏السَّوَائِبَ ‏","","",""],[7386,7386,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏عَنْ ‏ ‏أَبِي عُرْوَةَ مَعْمَرٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ تَابَ قَبْلَ أَنْ تَطْلُعَ الشَّمْسُ مِنْ مَغْرِبِهَا قُبِلَ مِنْهُ ‏","","",""],[7387,7387,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلُّ مَوْلُودٍ يُولَدُ عَلَى الْفِطْرَةِ فَأَبَوَاهُ يُهَوِّدَانِهِ وَيُنَصِّرَانِهِ وَيُمَجِّسَانِهِ كَمَا تُنْتَجُ الْبَهِيمَةُ هَلْ تُحِسُّونَ فِيهَا مِنْ ‏ ‏جَدْعَاءَ ‏ ‏ثُمَّ يَقُولُ وَاقْرَءُوا إِنْ شِئْتُمْ ‏ { ‏فِطْرَةَ اللَّهِ الَّتِي فَطَرَ النَّاسَ عَلَيْهَا لَا تَبْدِيلَ لِخَلْقِ اللَّهِ ‏}","","",""],[7388,7388,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏بَنِي غِفَارٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَقَدْ أَعْذَرَ اللَّهُ إِلَى عَبْدٍ أَحْيَاهُ حَتَّى بَلَغَ سِتِّينَ ‏ ‏أَوْ سَبْعِينَ ‏ ‏سَنَةً لَقَدْ أَعْذَرَ اللَّهُ لَقَدْ أَعْذَرَ اللَّهُ إِلَيْهِ ‏","","",""],[7389,7389,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏الْقَاسِمُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ ‏ ‏اجْتَمَعَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏وَكَعْبٌ ‏ ‏فَجَعَلَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏يُحَدِّثُ ‏ ‏كَعْبًا ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَكَعْبٌ ‏ ‏يُحَدِّثُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏عَنْ الْكُتُبِ ‏ ‏قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِكُلِّ نَبِيٍّ دَعْوَةٌ مُسْتَجَابَةٌ وَإِنِّي اخْتَبَأْتُ دَعْوَتِي شَفَاعَةً لِأُمَّتِي يَوْمَ الْقِيَامَةِ ‏","","",""],[7390,7390,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏ابْنِ طَاوُسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏لَأَطُوفَنَّ اللَّيْلَةَ بِمِائَةِ امْرَأَةٍ تَلِدُ كُلُّ امْرَأَةٍ مِنْهُنَّ غُلَامًا يُقَاتِلُ فِي سَبِيلِ اللَّهِ قَالَ وَنَسِيَ أَنْ يَقُولَ إِنْ شَاءَ اللَّهُ فَأَطَافَ بِهِنَّ قَالَ فَلَمْ تَلِدْ مِنْهُنَّ إِلَّا وَاحِدَةٌ نِصْفَ إِنْسَانٍ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ قَالَ إِنْ شَاءَ اللَّهُ لَمْ ‏ ‏يَحْنَثْ ‏ ‏وَكَانَ ‏ ‏دَرَكًا ‏ ‏لِحَاجَتِهِ ‏","","",""],[7391,7391,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِنَّ اللَّهَ تَعَالَى قَالَ ‏ ‏لَا يَقُلْ أَحَدُكُمْ يَا خَيْبَةَ الدَّهْرِ فَإِنِّي أَنَا الدَّهْرُ أُقَلِّبُ لَيْلَهُ وَنَهَارَهُ فَإِذَا شِئْتُ قَبَضْتُهُمَا ‏","","",""],[7392,7392,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ اللَّيْثِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ النَّاسُ يَا رَسُولَ اللَّهِ هَلْ نَرَى رَبَّنَا يَوْمَ الْقِيَامَةِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَلْ ‏ ‏تُضَارُّونَ ‏ ‏فِي الشَّمْسِ لَيْسَ دُونَهَا سَحَابٌ قَالُوا لَا يَا رَسُولَ اللَّهِ فَقَالَ هَلْ ‏ ‏تُضَارُّونَ ‏ ‏فِي الْقَمَرِ لَيْلَةَ الْبَدْرِ لَيْسَ دُونَهُ سَحَابٌ فَقَالُوا لَا يَا رَسُولَ اللَّهِ قَالَ فَإِنَّكُمْ تَرَوْنَهُ يَوْمَ الْقِيَامَةِ كَذَلِكَ يَجْمَعُ اللَّهُ النَّاسَ فَيَقُولُ مَنْ كَانَ يَعْبُدُ شَيْئًا فَيَتْبَعُهُ فَيَتْبَعُ مَنْ كَانَ يَعْبُدُ الْقَمَرَ الْقَمَرَ وَمَنْ كَانَ يَعْبُدُ الشَّمْسَ الشَّمْسَ وَيَتْبَعُ مَنْ كَانَ يَعْبُدُ ‏ ‏الطَّوَاغِيتَ ‏ ‏الطَّوَاغِيتَ ‏ ‏وَتَبْقَى هَذِهِ الْأُمَّةُ فِيهَا مُنَافِقُوهَا ‏ ‏فَيَأْتِيهِمْ اللَّهُ عَزَّ وَجَلَّ فِي غَيْرِ الصُّورَةِ الَّتِي تَعْرِفُونَ فَيَقُولُ أَنَا رَبُّكُمْ فَيَقُولُونَ نَعُوذُ بِاللَّهِ مِنْكَ هَذَا مَكَانُنَا حَتَّى يَأْتِيَنَا رَبُّنَا فَإِذَا جَاءَ رَبُّنَا عَرَفْنَاهُ قَالَ ‏ ‏فَيَأْتِيهِمْ اللَّهُ عَزَّ وَجَلَّ فِي الصُّورَةِ الَّتِي يَعْرِفُونَ فَيَقُولُ ‏ ‏أَنَا رَبُّكُمْ فَيَقُولُونَ أَنْتَ رَبُّنَا فَيَتْبَعُونَهُ قَالَ وَيُضْرَبُ جِسْرٌ عَلَى جَهَنَّمَ قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَكُونُ أَوَّلَ مَنْ ‏ ‏يُجِيزُ ‏ ‏وَدَعْوَى الرُّسُلِ يَوْمَئِذٍ اللَّهُمَّ سَلِّمْ سَلِّمْ وَبِهَا ‏ ‏كَلَالِيبُ ‏ ‏مِثْلُ ‏ ‏شَوْكِ السَّعْدَانِ ‏ ‏هَلْ رَأَيْتُمْ ‏ ‏شَوْكَ السَّعْدَانِ ‏ ‏قَالُوا نَعَمْ يَا رَسُولَ اللَّهِ ‏ ‏قَالَ فَإِنَّهَا مِثْلُ ‏ ‏شَوْكِ السَّعْدَانِ ‏ ‏غَيْرَ أَنَّهُ لَا يَعْلَمُ قَدْرَ عِظَمِهَا إِلَّا اللَّهُ تَعَالَى فَتَخْطَفُ النَّاسَ بِأَعْمَالِهِمْ فَمِنْهُمْ ‏ ‏الْمُوبَقُ ‏ ‏بِعَمَلِهِ وَمِنْهُمْ ‏ ‏الْمُخَرْدَلُ ‏ ‏ثُمَّ ‏ ‏يَنْجُو حَتَّى إِذَا فَرَغَ اللَّهُ عَزَّ وَجَلَّ مِنْ الْقَضَاءِ بَيْنَ الْعِبَادِ وَأَرَادَ أَنْ يُخْرِجَ مِنْ النَّارِ مَنْ أَرَادَ أَنْ يَرْحَمَ مِمَّنْ كَانَ يَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ أَمَرَ الْمَلَائِكَةَ أَنْ يُخْرِجُوهُمْ فَيَعْرِفُونَهُمْ بِعَلَامَةِ آثَارِ السُّجُودِ وَحَرَّمَ اللَّهُ عَلَى النَّارِ أَنْ تَأْكُلَ مِنْ ابْنِ ‏ ‏آدَمَ ‏ ‏أَثَرَ السُّجُودِ فَيُخْرِجُونَهُمْ قَدْ ‏ ‏امْتُحِشُوا ‏ ‏فَيُصَبُّ عَلَيْهِمْ مِنْ مَاءٍ يُقَالُ لَهُ مَاءُ الْحَيَاةِ فَيَنْبُتُونَ نَبَاتَ الْحِبَّةِ فِي ‏ ‏حَمِيلِ ‏ ‏السَّيْلِ وَيَبْقَى رَجُلٌ يُقْبِلُ بِوَجْهِهِ إِلَى النَّارِ فَيَقُولُ أَيْ رَبِّ قَدْ ‏ ‏قَشَبَنِي ‏ ‏رِيحُهَا وَأَحْرَقَنِي ‏ ‏ذَكَاؤُهَا ‏ ‏فَاصْرِفْ وَجْهِي عَنْ النَّارِ فَلَا يَزَالُ يَدْعُو اللَّهَ حَتَّى يَقُولَ فَلَعَلِّي إِنْ أَعْطَيْتُكَ ذَلِكَ أَنْ تَسْأَلَنِي غَيْرَهُ فَيَقُولُ لَا وَعِزَّتِكَ لَا أَسْأَلُكَ غَيْرَهُ فَيَصْرِفُ وَجْهَهُ عَنْ النَّارِ فَيَقُولُ بَعْدَ ذَلِكَ يَا رَبِّ قَرِّبْنِي إِلَى بَابِ الْجَنَّةِ فَيَقُولُ أَوَلَيْسَ قَدْ زَعَمْتَ أَنْ لَا تَسْأَلَنِي غَيْرَهُ وَيْلَكَ يَا ابْنَ ‏ ‏آدَمَ ‏ ‏مَا أَغْدَرَكَ فَلَا يَزَالُ يَدْعُو حَتَّى يَقُولَ فَلَعَلِّي إِنْ أَعْطَيْتُكَ أَنْ تَسْأَلَنِي غَيْرَهُ فَيَقُولُ لَا وَعِزَّتِكَ لَا أَسْأَلُكَ غَيْرَهُ وَيُعْطِي مِنْ عُهُودِهِ وَمَوَاثِيقِهِ أَنْ لَا يَسْأَلَ غَيْرَهُ فَيُقَرِّبُهُ إِلَى بَابِ الْجَنَّةِ فَإِذَا دَنَا مِنْهَا ‏ ‏انْفَهَقَتْ ‏ ‏لَهُ الْجَنَّةُ فَإِذَا رَأَى مَا فِيهَا مِنْ ‏ ‏الْحِبَرَةِ ‏ ‏وَالسُّرُورِ سَكَتَ مَا شَاءَ اللَّهُ أَنْ يَسْكُتَ ثُمَّ يَقُولُ يَا رَبِّ أَدْخِلْنِي الْجَنَّةَ فَيَقُولُ أَوَلَيْسَ قَدْ زَعَمْتَ أَنْ لَا تَسْأَلَ غَيْرَهُ وَقَدْ أَعْطَيْتَ عُهُودَكَ وَمَوَاثِيقَكَ أَنْ لَا تَسْأَلَنِي غَيْرَهُ فَيَقُولُ يَا رَبِّ لَا تَجْعَلْنِي أَشْقَى خَلْقِكَ فَلَا يَزَالُ يَدْعُو اللَّهَ حَتَّى يَضْحَكَ اللَّهُ فَإِذَا ضَحِكَ مِنْهُ أَذِنَ لَهُ بِالدُّخُولِ فِيهَا فَإِذَا أُدْخِلَ قِيلَ لَهُ تَمَنَّ مِنْ كَذَا فَيَتَمَنَّى ثُمَّ يُقَالُ تَمَنَّ مِنْ كَذَا فَيَتَمَنَّى حَتَّى تَنْقَطِعَ بِهِ الْأَمَانِيُّ فَيُقَالُ لَهُ هَذَا لَكَ وَمِثْلُهُ مَعَهُ قَالَ ‏ ‏وَأَبُو سَعِيدٍ ‏ ‏جَالِسٌ مَعَ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَلَا يُغَيِّرُ عَلَيْهِ شَيْئًا مِنْ قَوْلِهِ حَتَّى إِذَا انْتَهَى إِلَى قَوْلِهِ هَذَا لَكَ وَمِثْلُهُ مَعَهُ ‏ ‏قَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ هَذَا لَكَ وَعَشَرَةُ أَمْثَالِهِ مَعَهُ قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏حَفِظْتُ مِثْلُهُ مَعَهُ ‏ ‏قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏وَذَلِكَ الرَّجُلُ آخِرُ أَهْلِ الْجَنَّةِ دُخُولًا الْجَنَّةَ ‏","","",""],[7393,7393,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏احْتَجَّتْ الْجَنَّةُ وَالنَّارُ فَقَالَتْ الْجَنَّةُ يَا رَبِّ مَا لِي لَا يَدْخُلُنِي إِلَّا فُقَرَاءُ النَّاسِ ‏ ‏وَسَقَطُهُمْ ‏ ‏وَقَالَتْ النَّارُ مَا لِي لَا يَدْخُلُنِي إِلَّا الْجَبَّارُونَ وَالْمُتَكَبِّرُونَ فَقَالَ لِلنَّارِ أَنْتِ عَذَابِي أُصِيبُ بِكِ مَنْ أَشَاءُ وَقَالَ لِلْجَنَّةِ أَنْتِ رَحْمَتِي أُصِيبُ بِكِ مَنْ أَشَاءُ وَلِكُلِّ وَاحِدَةٍ مِنْكُمَا مِلْؤُهَا فَأَمَّا الْجَنَّةُ فَإِنَّ اللَّهَ يُنْشِئُ لَهَا مَا يَشَاءُ وَأَمَّا النَّارُ فَيُلْقَوْنَ فِيهَا وَتَقُولُ ‏ { ‏هَلْ مِنْ مَزِيدٍ ‏} ‏حَتَّى يَضَعَ قَدَمَهُ فِيهَا فَهُنَالِكَ تَمْتَلِئُ ‏ ‏وَيُزْوَى بَعْضُهَا إِلَى بَعْضٍ وَتَقُولُ قَطْ قَطْ قَطْ ‏","","",""],[7394,7394,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏ابْنِ طَاوُسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏مَا رَأَيْتُ شَيْئًا أَشْبَهَ ‏ ‏بِاللَّمَمِ ‏ ‏مِمَّا ‏ ‏قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ كَتَبَ عَلَى ابْنِ ‏ ‏آدَمَ ‏ ‏حَظَّهُ مِنْ الزِّنَا أَدْرَكَهُ لَا مَحَالَةَ وَزِنَا الْعَيْنِ النَّظَرُ وَزِنَا اللِّسَانِ النُّطْقُ وَالنَّفْسُ تَمَنَّى وَتَشْتَهِي وَالْفَرْجُ يُصَدِّقُ ذَلِكَ أَوْ يُكَذِّبُهُ ‏","","",""],[7395,7395,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ رَجُلٍ لَا يُؤَدِّي زَكَاةَ مَالِهِ إِلَّا جُعِلَ يَوْمَ الْقِيَامَةِ صَفَائِحُ مِنْ نَارٍ ‏ ‏يُكْوَى بِهَا جَبِينُهُ وَجَبْهَتُهُ وَظَهْرُهُ فِي يَوْمٍ كَانَ مِقْدَارُهُ خَمْسِينَ أَلْفَ سَنَةٍ ‏ ‏تَطَؤُهُ ‏ ‏بِأَخْفَافِهَا ‏ ‏حَسِبْتُهُ قَالَ وَتَعَضُّهُ بِأَفْوَاهِهَا ‏ ‏يَرِدُ أَوَّلُهَا عَنْ آخِرِهَا حَتَّى ‏ ‏يُقْضَى بَيْنَ النَّاسِ ثُمَّ يُرَى سَبِيلَهُ وَإِنْ كَانَتْ غَنَمًا فَكَمِثْلِ ذَلِكَ إِلَّا أَنَّهَا تَنْطَحُهُ بِقُرُونِهَا ‏ ‏وَتَطَؤُهُ ‏ ‏بِأَظْلَافِهَا ‏","","",""],[7396,7396,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ قَالَ ‏ ‏مَعْمَرٌ ‏ ‏أَخْبَرَنِي ‏ ‏الزُّهْرِيُّ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ مَاتَ لَهُ ثَلَاثَةٌ لَمْ يَبْلُغُوا ‏ ‏الْحِنْثَ ‏ ‏لَمْ تَمَسَّهُ النَّارُ إِلَّا ‏ ‏تَحِلَّةَ الْقَسَمِ ‏ ‏يَعْنِي الْوُرُودَ ‏","","",""],[7397,7397,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏اشْتَكَتْ النَّارُ إِلَى رَبِّهَا فَقَالَتْ رَبِّ أَكَلَ بَعْضِي بَعْضًا فَنَفِّسْنِي فَأَذِنَ لَهَا فِي كُلِّ عَامٍ بِنَفَسَيْنِ فَأَشَدُّ مَا تَجِدُونَ مِنْ الْبَرْدِ مِنْ زَمْهَرِيرِ جَهَنَّمَ وَأَشَدُّ مَا تَجِدُونَ مِنْ الْحَرِّ مِنْ حَرِّ جَهَنَّمَ ‏","","",""],[7398,7398,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامُ بْنُ حَسَّانَ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏لَمَّا نَزَلَتْ ‏ ‏إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَاكُمْ أَهْلُ ‏ ‏الْيَمَنِ ‏ ‏هُمْ أَرَقُّ قُلُوبًا الْإِيمَانُ يَمَانٍ الْفِقْهُ يَمَانٍ الْحِكْمَةُ يَمَانِيَةٌ ‏","","",""],[7399,7399,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏وَكَانَ ‏ ‏مَعْمَرٌ ‏ ‏يَقُولُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏ثُمَّ قَالَ بَعْدُ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏فِي زَكَاةِ الْفِطْرِ ‏ ‏عَلَى كُلِّ حُرٍّ وَعَبْدٍ ذَكَرٍ أَوْ أُنْثَى صَغِيرٍ أَوْ كَبِيرٍ فَقِيرٍ أَوْ غَنِيٍّ صَاعٌ مِنْ تَمْرٍ أَوْ نِصْفُ صَاعٍ مِنْ قَمْحٍ قَالَ ‏ ‏مَعْمَرٌ ‏ ‏وَبَلَغَنِي أَنَّ ‏ ‏الزُّهْرِيَّ ‏ ‏كَانَ يَرْوِيهِ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[7400,7400,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏أَبِي الرَّبِيعِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏عَهِدَ إِلَيَّ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ثَلَاثٍ لَا أَدَعُهُنَّ أَبَدًا ‏ ‏لَا أَنَامُ إِلَّا عَلَى ‏ ‏وِتْرٍ ‏ ‏وَفِي صَلَاةِ الضُّحَى وَصِيَامِ ثَلَاثَةِ أَيَّامٍ مِنْ كُلِّ شَهْرٍ ‏","","",""]];
